import SwiftUI
import HelmUI

/// The in-app changelog: structured and localized through the same `L()` tables
/// as the rest of the UI, so "What's New" reads in the user's language. The
/// repo's CHANGELOG.md stays the canonical English record for GitHub.
enum ChangeKind {
    case new, upd, fix

    /// NEW / UPD / FIX, the same three letters in every language.
    ///
    /// They were words — "Улучшено", "Correctif", "Melhoria" — and a word is a
    /// different length in each of eight languages and in each of three kinds.
    /// The badges sit in a column down the left of the list, so the widest one
    /// set the indent for every entry and the column came out ragged: Russian
    /// "Улучшено" ran half again as wide as "Испр." beside it. Three letters,
    /// uppercase, untranslated — the same convention as BETA and DEV, and the
    /// same width whatever the reader's language.
    var label: String {
        switch self {
        case .new: return "NEW"
        case .upd: return "UPD"
        case .fix: return "FIX"
        }
    }

    var color: Color {
        switch self {
        case .new: return .green
        case .upd: return .blue
        case .fix: return .orange
        }
    }
}

struct ChangeItem: Identifiable {
    let id = UUID()
    let kind: ChangeKind
    let text: String
}

struct ChangelogEntry: Identifiable {
    var id: String { version }
    let version: String
    let date: String
    let items: [ChangeItem]
}

enum Changelog {
    /// Computed so `L()` resolves against the current language each time.
    static var entries: [ChangelogEntry] {
        [
            ChangelogEntry(version: "0.7.2", date: "2026-07-28", items: [
                ChangeItem(kind: .new, text: L("A way out of a scan in Disk. The module opens on whatever it measured last, and the only button was \u{201C}Scan again\u{201D}, which measures the same place — so a scan of the wrong folder came back at every launch with no way to leave it. \u{201C}Choose another\u{2026}\u{201D} beside it clears the screen and forgets the saved scan.", [.ru: "\u{0418}\u{0437} \u{0441}\u{043A}\u{0430}\u{043D}\u{0430} \u{0432} \u{00AB}\u{0414}\u{0438}\u{0441}\u{043A}\u{0435}\u{00BB} \u{0442}\u{0435}\u{043F}\u{0435}\u{0440}\u{044C} \u{0435}\u{0441}\u{0442}\u{044C} \u{0432}\u{044B}\u{0445}\u{043E}\u{0434}. \u{041C}\u{043E}\u{0434}\u{0443}\u{043B}\u{044C} \u{043E}\u{0442}\u{043A}\u{0440}\u{044B}\u{0432}\u{0430}\u{0435}\u{0442}\u{0441}\u{044F} \u{043D}\u{0430} \u{0442}\u{043E}\u{043C}, \u{0447}\u{0442}\u{043E} \u{043C}\u{0435}\u{0440}\u{0438}\u{043B} \u{0432} \u{043F}\u{043E}\u{0441}\u{043B}\u{0435}\u{0434}\u{043D}\u{0438}\u{0439} \u{0440}\u{0430}\u{0437}, \u{0430} \u{0435}\u{0434}\u{0438}\u{043D}\u{0441}\u{0442}\u{0432}\u{0435}\u{043D}\u{043D}\u{0430}\u{044F} \u{043A}\u{043D}\u{043E}\u{043F}\u{043A}\u{0430} \u{0431}\u{044B}\u{043B}\u{0430} \u{00AB}\u{0421}\u{043A}\u{0430}\u{043D}\u{0438}\u{0440}\u{043E}\u{0432}\u{0430}\u{0442}\u{044C} \u{0437}\u{0430}\u{043D}\u{043E}\u{0432}\u{043E}\u{00BB}, \u{043A}\u{043E}\u{0442}\u{043E}\u{0440}\u{0430}\u{044F} \u{043C}\u{0435}\u{0440}\u{0438}\u{0442} \u{0442}\u{043E} \u{0436}\u{0435} \u{0441}\u{0430}\u{043C}\u{043E}\u{0435} \u{043C}\u{0435}\u{0441}\u{0442}\u{043E}. \u{00AB}\u{0412}\u{044B}\u{0431}\u{0440}\u{0430}\u{0442}\u{044C} \u{0434}\u{0440}\u{0443}\u{0433}\u{043E}\u{0435}\u{2026}\u{00BB} \u{0440}\u{044F}\u{0434}\u{043E}\u{043C} \u{043E}\u{0447}\u{0438}\u{0449}\u{0430}\u{0435}\u{0442} \u{044D}\u{043A}\u{0440}\u{0430}\u{043D} \u{0438} \u{0437}\u{0430}\u{0431}\u{044B}\u{0432}\u{0430}\u{0435}\u{0442} \u{0441}\u{043E}\u{0445}\u{0440}\u{0430}\u{043D}\u{0451}\u{043D}\u{043D}\u{044B}\u{0439} \u{0441}\u{043A}\u{0430}\u{043D}.", .es: "Una salida del escaneo en Disco: el m\u{00F3}dulo se abre en lo \u{00FA}ltimo que midi\u{00F3} y \u{00AB}Elegir otro\u{2026}\u{00BB} limpia la pantalla y olvida el escaneo guardado.", .fr: "Une sortie de l\u{2019}analyse dans Disque : le module s\u{2019}ouvre sur ce qu\u{2019}il a mesur\u{00E9} en dernier, et \u{00AB} Choisir autre chose\u{2026} \u{00BB} efface l\u{2019}\u{00E9}cran et oublie l\u{2019}analyse enregistr\u{00E9}e.", .de: "Ein Ausgang aus dem Scan in Festplatte: das Modul \u{00F6}ffnet mit dem zuletzt Gemessenen, und \u{201E}Anderes w\u{00E4}hlen\u{2026}\u{201C} leert den Bildschirm und vergisst den gespeicherten Scan.", .ja: "\u{300C}\u{30C7}\u{30A3}\u{30B9}\u{30AF}\u{300D}\u{306E}\u{30B9}\u{30AD}\u{30E3}\u{30F3}\u{304B}\u{3089}\u{629C}\u{3051}\u{3089}\u{308C}\u{308B}\u{3088}\u{3046}\u{306B}\u{306A}\u{308A}\u{307E}\u{3057}\u{305F}\u{3002}\u{300C}\u{5225}\u{306E}\u{5834}\u{6240}\u{3092}\u{9078}\u{629E}\u{2026}\u{300D}\u{3067}\u{4FDD}\u{5B58}\u{6E08}\u{307F}\u{306E}\u{30B9}\u{30AD}\u{30E3}\u{30F3}\u{3092}\u{5FD8}\u{308C}\u{307E}\u{3059}\u{3002}", .zh: "\u{201C}\u{78C1}\u{76D8}\u{201D}\u{4E2D}\u{7EC8}\u{4E8E}\u{6709}\u{4E86}\u{9000}\u{51FA}\u{626B}\u{63CF}\u{7684}\u{529E}\u{6CD5}\u{FF1A}\u{201C}\u{9009}\u{62E9}\u{5176}\u{4ED6}\u{2026}\u{201D}\u{4F1A}\u{6E05}\u{7A7A}\u{754C}\u{9762}\u{5E76}\u{5FD8}\u{8BB0}\u{5DF2}\u{4FDD}\u{5B58}\u{7684}\u{626B}\u{63CF}\u{3002}", .pt: "Uma sa\u{00ED}da do escaneamento em Disco: o m\u{00F3}dulo abre no que mediu por \u{00FA}ltimo, e \u{00AB}Escolher outro\u{2026}\u{00BB} limpa a tela e esquece o escaneamento salvo."])),
                ChangeItem(kind: .upd, text: L("Moving around the disk ring is one movement now. Going back up more than one level used to change the screen without animating at all, the ring travels for longer the further it goes, and the slight overshoot at the end of each move — which read as a snap — is gone.", [.ru: "\u{041F}\u{0435}\u{0440}\u{0435}\u{043C}\u{0435}\u{0449}\u{0435}\u{043D}\u{0438}\u{0435} \u{043F}\u{043E} \u{043A}\u{043E}\u{043B}\u{044C}\u{0446}\u{0443} \u{00AB}\u{0414}\u{0438}\u{0441}\u{043A}\u{0430}\u{00BB} \u{0442}\u{0435}\u{043F}\u{0435}\u{0440}\u{044C} \u{043E}\u{0434}\u{043D}\u{043E} \u{0434}\u{0432}\u{0438}\u{0436}\u{0435}\u{043D}\u{0438}\u{0435}. \u{0412}\u{043E}\u{0437}\u{0432}\u{0440}\u{0430}\u{0442} \u{0431}\u{043E}\u{043B}\u{0435}\u{0435} \u{0447}\u{0435}\u{043C} \u{043D}\u{0430} \u{043E}\u{0434}\u{0438}\u{043D} \u{0443}\u{0440}\u{043E}\u{0432}\u{0435}\u{043D}\u{044C} \u{0440}\u{0430}\u{043D}\u{044C}\u{0448}\u{0435} \u{043D}\u{0435} \u{0430}\u{043D}\u{0438}\u{043C}\u{0438}\u{0440}\u{043E}\u{0432}\u{0430}\u{043B}\u{0441}\u{044F} \u{0432}\u{043E}\u{0432}\u{0441}\u{0435} — \u{044D}\u{043A}\u{0440}\u{0430}\u{043D} \u{043F}\u{0440}\u{043E}\u{0441}\u{0442}\u{043E} \u{043C}\u{0435}\u{043D}\u{044F}\u{043B}\u{0441}\u{044F}. \u{0427}\u{0435}\u{043C} \u{0434}\u{0430}\u{043B}\u{044C}\u{0448}\u{0435} \u{0435}\u{0434}\u{0435}\u{0442} \u{043A}\u{043E}\u{043B}\u{044C}\u{0446}\u{043E}, \u{0442}\u{0435}\u{043C} \u{0434}\u{043E}\u{043B}\u{044C}\u{0448}\u{0435} \u{0434}\u{0432}\u{0438}\u{0436}\u{0435}\u{043D}\u{0438}\u{0435}, \u{0430} \u{043B}\u{0451}\u{0433}\u{043A}\u{0438}\u{0439} \u{043F}\u{0435}\u{0440}\u{0435}\u{043B}\u{0451}\u{0442} \u{0432} \u{043A}\u{043E}\u{043D}\u{0446}\u{0435}, \u{0447}\u{0438}\u{0442}\u{0430}\u{0432}\u{0448}\u{0438}\u{0439}\u{0441}\u{044F} \u{043A}\u{0430}\u{043A} \u{0440}\u{044B}\u{0432}\u{043E}\u{043A}, \u{0443}\u{0431}\u{0440}\u{0430}\u{043D}.", .es: "Moverse por el anillo del disco es un solo movimiento: subir m\u{00E1}s de un nivel no se animaba en absoluto, ahora el anillo tarda m\u{00E1}s cuanto m\u{00E1}s lejos va, y el peque\u{00F1}o rebote final ha desaparecido.", .fr: "Se d\u{00E9}placer dans l\u{2019}anneau du disque est un seul mouvement : remonter de plus d\u{2019}un niveau ne s\u{2019}animait pas du tout, l\u{2019}anneau prend maintenant plus de temps quand il va plus loin, et le l\u{00E9}ger rebond final a disparu.", .de: "Die Bewegung im Festplattenring ist eine Bewegung: mehr als eine Ebene zur\u{00FC}ck wurde gar nicht animiert, der Ring braucht jetzt l\u{00E4}nger, je weiter er geht, und das leichte \u{00DC}berschwingen am Ende ist weg.", .ja: "\u{30C7}\u{30A3}\u{30B9}\u{30AF}\u{30EA}\u{30F3}\u{30B0}\u{306E}\u{79FB}\u{52D5}\u{304C}\u{4E00}\u{3064}\u{306E}\u{52D5}\u{304D}\u{306B}\u{306A}\u{308A}\u{307E}\u{3057}\u{305F}\u{3002}2 \u{968E}\u{5C64}\u{4EE5}\u{4E0A}\u{623B}\u{308B}\u{3068}\u{304D}\u{306F}\u{30A2}\u{30CB}\u{30E1}\u{30FC}\u{30B7}\u{30E7}\u{30F3}\u{304C}\u{306A}\u{304F}\u{3001}\u{753B}\u{9762}\u{304C}\u{5207}\u{308A}\u{66FF}\u{308F}\u{308B}\u{3060}\u{3051}\u{3067}\u{3057}\u{305F}\u{3002}", .zh: "\u{5728}\u{78C1}\u{76D8}\u{73AF}\u{5F62}\u{56FE}\u{4E2D}\u{79FB}\u{52A8}\u{73B0}\u{5728}\u{662F}\u{4E00}\u{4E2A}\u{8FDE}\u{8D2F}\u{7684}\u{52A8}\u{4F5C}\u{FF1A}\u{5411}\u{4E0A}\u{8DE8}\u{8D8A}\u{591A}\u{5C42}\u{65F6}\u{4E4B}\u{524D}\u{5B8C}\u{5168}\u{6CA1}\u{6709}\u{52A8}\u{753B}\u{3002}", .pt: "Mover-se pelo anel do disco \u{00E9} um s\u{00F3} movimento: subir mais de um n\u{00ED}vel n\u{00E3}o animava nada, agora o anel leva mais tempo quanto mais longe vai, e o pequeno repique no fim sumiu."])),
                ChangeItem(kind: .upd, text: L("The disk ring grows into the folder you opened. It shows three levels at a time, and the level that arrived when you drilled in had nowhere to come from — it appeared all at once at the end of the animation. Now it slides in with the rest.", [.ru: "\u{041A}\u{043E}\u{043B}\u{044C}\u{0446}\u{043E} \u{00AB}\u{0414}\u{0438}\u{0441}\u{043A}\u{0430}\u{00BB} \u{0442}\u{0435}\u{043F}\u{0435}\u{0440}\u{044C} \u{0432}\u{0440}\u{0430}\u{0441}\u{0442}\u{0430}\u{0435}\u{0442} \u{0432} \u{043F}\u{0430}\u{043F}\u{043A}\u{0443}, \u{0432} \u{043A}\u{043E}\u{0442}\u{043E}\u{0440}\u{0443}\u{044E} \u{0432}\u{044B} \u{0432}\u{043E}\u{0448}\u{043B}\u{0438}. \u{041E}\u{043D}\u{043E} \u{043F}\u{043E}\u{043A}\u{0430}\u{0437}\u{044B}\u{0432}\u{0430}\u{0435}\u{0442} \u{0442}\u{0440}\u{0438} \u{0443}\u{0440}\u{043E}\u{0432}\u{043D}\u{044F} \u{0441}\u{0440}\u{0430}\u{0437}\u{0443}, \u{0438} \u{0442}\u{0440}\u{0435}\u{0442}\u{0438}\u{0439} \u{0443}\u{0440}\u{043E}\u{0432}\u{0435}\u{043D}\u{044C} \u{043F}\u{043E}\u{044F}\u{0432}\u{043B}\u{044F}\u{043B}\u{0441}\u{044F} \u{0440}\u{0435}\u{0437}\u{043A}\u{043E} \u{0432} \u{043A}\u{043E}\u{043D}\u{0446}\u{0435} \u{0430}\u{043D}\u{0438}\u{043C}\u{0430}\u{0446}\u{0438}\u{0438} — \u{0435}\u{043C}\u{0443} \u{0431}\u{044B}\u{043B}\u{043E} \u{043F}\u{0440}\u{043E}\u{0441}\u{0442}\u{043E} \u{043D}\u{0435}\u{043E}\u{0442}\u{043A}\u{0443}\u{0434}\u{0430} \u{0435}\u{0445}\u{0430}\u{0442}\u{044C}. \u{0422}\u{0435}\u{043F}\u{0435}\u{0440}\u{044C} \u{043E}\u{043D} \u{0432}\u{044A}\u{0435}\u{0437}\u{0436}\u{0430}\u{0435}\u{0442} \u{0432}\u{043C}\u{0435}\u{0441}\u{0442}\u{0435} \u{0441}\u{043E} \u{0432}\u{0441}\u{0435}\u{043C}\u{0438}.", .es: "El anillo del disco crece hacia la carpeta que abriste: el nivel que llegaba al entrar aparec\u{00ED}a de golpe al final de la animaci\u{00F3}n y ahora entra desliz\u{00E1}ndose con los dem\u{00E1}s.", .fr: "L\u{2019}anneau du disque grandit vers le dossier ouvert : le niveau qui arrivait apparaissait d\u{2019}un coup \u{00E0} la fin de l\u{2019}animation, il glisse maintenant avec les autres.", .de: "Der Festplattenring w\u{00E4}chst in den ge\u{00F6}ffneten Ordner hinein: die Ebene, die beim Hineingehen dazukam, erschien am Ende der Animation schlagartig und gleitet jetzt mit herein.", .ja: "\u{30C7}\u{30A3}\u{30B9}\u{30AF}\u{306E}\u{30EA}\u{30F3}\u{30B0}\u{304C}\u{958B}\u{3044}\u{305F}\u{30D5}\u{30A9}\u{30EB}\u{30C0}\u{3078}\u{6ED1}\u{3089}\u{304B}\u{306B}\u{5165}\u{308A}\u{307E}\u{3059}\u{3002}\u{4E09}\u{5C64}\u{76EE}\u{304C}\u{30A2}\u{30CB}\u{30E1}\u{30FC}\u{30B7}\u{30E7}\u{30F3}\u{306E}\u{6700}\u{5F8C}\u{306B}\u{7A81}\u{7136}\u{73FE}\u{308C}\u{308B}\u{3053}\u{3068}\u{306F}\u{306A}\u{304F}\u{306A}\u{308A}\u{307E}\u{3057}\u{305F}\u{3002}", .zh: "\u{78C1}\u{76D8}\u{73AF}\u{5F62}\u{56FE}\u{4F1A}\u{5E73}\u{6ED1}\u{5730}\u{751F}\u{957F}\u{5230}\u{4F60}\u{6253}\u{5F00}\u{7684}\u{6587}\u{4EF6}\u{5939}\u{FF1A}\u{7B2C}\u{4E09}\u{5C42}\u{4E0D}\u{518D}\u{5728}\u{52A8}\u{753B}\u{7ED3}\u{675F}\u{65F6}\u{7A81}\u{7136}\u{51FA}\u{73B0}\u{3002}", .pt: "O anel do disco cresce para dentro da pasta que voc\u{00EA} abriu: o n\u{00ED}vel que chegava aparecia de uma vez no fim da anima\u{00E7}\u{00E3}o e agora entra deslizando com os outros."])),
                ChangeItem(kind: .fix, text: L("The duplicate finder no longer holds on to everything it reads. It compares files a megabyte at a time so a video never has to fit in memory — but the app kept every one of those megabytes until the scan ended, so the memory it used followed the size of the folder rather than the size of a slice. Memory is also handed back to macOS when a scan finishes and when a module is switched off, instead of being kept for later.", [.ru: "\u{041F}\u{043E}\u{0438}\u{0441}\u{043A} \u{0434}\u{0443}\u{0431}\u{043B}\u{0438}\u{043A}\u{0430}\u{0442}\u{043E}\u{0432} \u{0431}\u{043E}\u{043B}\u{044C}\u{0448}\u{0435} \u{043D}\u{0435} \u{0434}\u{0435}\u{0440}\u{0436}\u{0438}\u{0442} \u{0432}\u{0441}\u{0451}, \u{0447}\u{0442}\u{043E} \u{043F}\u{0440}\u{043E}\u{0447}\u{0438}\u{0442}\u{0430}\u{043B}. \u{0424}\u{0430}\u{0439}\u{043B}\u{044B} \u{0441}\u{0440}\u{0430}\u{0432}\u{043D}\u{0438}\u{0432}\u{0430}\u{044E}\u{0442}\u{0441}\u{044F} \u{043F}\u{043E} \u{043C}\u{0435}\u{0433}\u{0430}\u{0431}\u{0430}\u{0439}\u{0442}\u{0443}, \u{0447}\u{0442}\u{043E}\u{0431}\u{044B} \u{0432}\u{0438}\u{0434}\u{0435}\u{043E} \u{043D}\u{0435} \u{043F}\u{0440}\u{0438}\u{0445}\u{043E}\u{0434}\u{0438}\u{043B}\u{043E}\u{0441}\u{044C} \u{0446}\u{0435}\u{043B}\u{0438}\u{043A}\u{043E}\u{043C} \u{0434}\u{0435}\u{0440}\u{0436}\u{0430}\u{0442}\u{044C} \u{0432} \u{043F}\u{0430}\u{043C}\u{044F}\u{0442}\u{0438}, \u{043D}\u{043E} \u{043A}\u{0430}\u{0436}\u{0434}\u{044B}\u{0439} \u{0442}\u{0430}\u{043A}\u{043E}\u{0439} \u{043C}\u{0435}\u{0433}\u{0430}\u{0431}\u{0430}\u{0439}\u{0442} \u{0436}\u{0438}\u{043B} \u{0434}\u{043E} \u{043A}\u{043E}\u{043D}\u{0446}\u{0430} \u{0441}\u{043A}\u{0430}\u{043D}\u{0430} — \u{0438} \u{043F}\u{0430}\u{043C}\u{044F}\u{0442}\u{044C} \u{0440}\u{043E}\u{0441}\u{043B}\u{0430} \u{043F}\u{043E} \u{0440}\u{0430}\u{0437}\u{043C}\u{0435}\u{0440}\u{0443} \u{043F}\u{0430}\u{043F}\u{043A}\u{0438}, \u{0430} \u{043D}\u{0435} \u{043F}\u{043E} \u{0440}\u{0430}\u{0437}\u{043C}\u{0435}\u{0440}\u{0443} \u{043A}\u{0443}\u{0441}\u{043A}\u{0430}. \u{041A}\u{0440}\u{043E}\u{043C}\u{0435} \u{0442}\u{043E}\u{0433}\u{043E}, \u{043F}\u{0430}\u{043C}\u{044F}\u{0442}\u{044C} \u{0442}\u{0435}\u{043F}\u{0435}\u{0440}\u{044C} \u{0432}\u{043E}\u{0437}\u{0432}\u{0440}\u{0430}\u{0449}\u{0430}\u{0435}\u{0442}\u{0441}\u{044F} \u{0441}\u{0438}\u{0441}\u{0442}\u{0435}\u{043C}\u{0435} \u{043F}\u{043E}\u{0441}\u{043B}\u{0435} \u{0441}\u{043A}\u{0430}\u{043D}\u{0430} \u{0438} \u{043F}\u{0440}\u{0438} \u{0432}\u{044B}\u{043A}\u{043B}\u{044E}\u{0447}\u{0435}\u{043D}\u{0438}\u{0438} \u{043C}\u{043E}\u{0434}\u{0443}\u{043B}\u{044F}, \u{0430} \u{043D}\u{0435} \u{043F}\u{0440}\u{0438}\u{0434}\u{0435}\u{0440}\u{0436}\u{0438}\u{0432}\u{0430}\u{0435}\u{0442}\u{0441}\u{044F} \u{043D}\u{0430} \u{043F}\u{043E}\u{0442}\u{043E}\u{043C}.", .es: "El buscador de duplicados ya no retiene todo lo que lee: la memoria segu\u{00ED}a el tama\u{00F1}o de la carpeta en vez del de un fragmento. Adem\u{00E1}s, la memoria se devuelve al sistema al terminar un escaneo y al apagar un m\u{00F3}dulo.", .fr: "Le chercheur de doublons ne conserve plus tout ce qu\u{2019}il lit : la m\u{00E9}moire suivait la taille du dossier plut\u{00F4}t que celle d\u{2019}un fragment. Elle est aussi rendue au syst\u{00E8}me \u{00E0} la fin d\u{2019}une analyse et \u{00E0} l\u{2019}extinction d\u{2019}un module.", .de: "Die Duplikatsuche h\u{00E4}lt nicht mehr alles fest, was sie liest: der Speicher folgte der Gr\u{00F6}\u{00DF}e des Ordners statt der eines St\u{00FC}cks. Er wird jetzt auch nach einem Scan und beim Ausschalten eines Moduls an das System zur\u{00FC}ckgegeben.", .ja: "\u{91CD}\u{8907}\u{30D5}\u{30A1}\u{30A4}\u{30EB}\u{691C}\u{7D22}\u{304C}\u{8AAD}\u{3093}\u{3060}\u{30C7}\u{30FC}\u{30BF}\u{3092}\u{6301}\u{3061}\u{7D9A}\u{3051}\u{306A}\u{304F}\u{306A}\u{308A}\u{307E}\u{3057}\u{305F}\u{3002}\u{30E1}\u{30E2}\u{30EA}\u{4F7F}\u{7528}\u{91CF}\u{304C}\u{30D5}\u{30A9}\u{30EB}\u{30C0}\u{30B5}\u{30A4}\u{30BA}\u{306B}\u{5F93}\u{3063}\u{3066}\u{5897}\u{3048}\u{3066}\u{3044}\u{307E}\u{3057}\u{305F}\u{3002}\u{30B9}\u{30AD}\u{30E3}\u{30F3}\u{5B8C}\u{4E86}\u{6642}\u{3068}\u{30E2}\u{30B8}\u{30E5}\u{30FC}\u{30EB}\u{7121}\u{52B9}\u{5316}\u{6642}\u{306B}\u{30E1}\u{30E2}\u{30EA}\u{3092}\u{8FD4}\u{3057}\u{307E}\u{3059}\u{3002}", .zh: "\u{91CD}\u{590D}\u{6587}\u{4EF6}\u{67E5}\u{627E}\u{4E0D}\u{518D}\u{4FDD}\u{7559}\u{5B83}\u{8BFB}\u{53D6}\u{7684}\u{5168}\u{90E8}\u{5185}\u{5BB9}\u{FF1A}\u{5185}\u{5B58}\u{5360}\u{7528}\u{66FE}\u{968F}\u{6587}\u{4EF6}\u{5939}\u{5927}\u{5C0F}\u{589E}\u{957F}\u{3002}\u{626B}\u{63CF}\u{7ED3}\u{675F}\u{548C}\u{5173}\u{95ED}\u{6A21}\u{5757}\u{65F6}\u{4F1A}\u{5C06}\u{5185}\u{5B58}\u{4EA4}\u{8FD8}\u{7CFB}\u{7EDF}\u{3002}", .pt: "O buscador de duplicatas n\u{00E3}o retém mais tudo o que l\u{00EA}: a mem\u{00F3}ria seguia o tamanho da pasta em vez do tamanho de um peda\u{00E7}o. Ela tamb\u{00E9}m volta ao sistema ao fim de um escaneamento e ao desligar um m\u{00F3}dulo."])),
                ChangeItem(kind: .fix, text: L("Sizes are right where they were nearly right. A file just under a round number was shown with the unit below it — \"1000 KB\" instead of \"1 MB\" — on every screen that names a size. And removing a folder now reports what the folder held, where it used to report nothing at all.", [.ru: "Размеры верны там, где были почти верны. Файл чуть меньше круглого числа показывался в меньшей единице — «1000 КБ» вместо «1 МБ» — на каждом экране, где есть размер. А удаление папки теперь сообщает, сколько в ней было, а не ноль.", .es: "Los tamaños son correctos donde antes casi lo eran: «1000 KB» en vez de «1 MB», en todas las pantallas. Y borrar una carpeta informa de lo que contenía.", .fr: "Les tailles sont justes là où elles l’étaient presque : « 1000 Ko » au lieu de « 1 Mo », sur tous les écrans. Et supprimer un dossier indique ce qu’il contenait.", .de: "Größen stimmen dort, wo sie fast stimmten: „1000 KB“ statt „1 MB“, auf jedem Bildschirm. Und das Löschen eines Ordners meldet, was darin war.", .ja: "サイズ表示を修正しました。「1 MB」となるべき場面で「1000 KB」と出ていました。フォルダを削除したときの解放量も正しくなりました。", .zh: "大小显示修正：本该是“1 MB”的地方显示成“1000 KB”。删除文件夹时也会正确统计释放的空间。", .pt: "Os tamanhos estão certos onde quase estavam: «1000 KB» em vez de «1 MB», em todas as telas. E apagar uma pasta informa o que ela continha."])),
                ChangeItem(kind: .fix, text: L("Duplicates keeps the copy that was there first, by the same \"Date Added\" the Finder shows. It used to keep whichever path came first alphabetically, so a copy on the Desktop beat the filed original and Helm offered the wrong one for deletion.", [.ru: "«Дубликаты» оставляют копию, появившуюся раньше, — по той же «дате добавления», что показывает Finder. Раньше побеждал первый путь по алфавиту, из-за чего копия на Рабочем столе выигрывала у убранного в папку оригинала.", .es: "Duplicados conserva la copia que estaba primero, por la misma «fecha de incorporación» que muestra el Finder, en vez del primer camino alfabético.", .fr: "Doublons conserve la copie présente en premier, d’après la même « date d’ajout » que le Finder, et non le premier chemin par ordre alphabétique.", .de: "Duplikate behält die Kopie, die zuerst da war — nach demselben „Hinzugefügt am“, das der Finder zeigt, statt nach dem alphabetisch ersten Pfad.", .ja: "「重複」は先にあったコピーを残します。Finder と同じ「追加日」で判断し、パスのアルファベット順ではなくなりました。", .zh: "“重复文件”会保留更早存在的那份，依据访达同样的“添加日期”，而不是路径的字母顺序。", .pt: "Duplicados mantém a cópia que estava lá primeiro, pela mesma «data de adição» que o Finder mostra, e não pelo primeiro caminho em ordem alfabética."])),
                ChangeItem(kind: .fix, text: L("Helm can be used with VoiceOver. Every control now says what it is — the rule editor was built from pop-up buttons and fields that announced nothing, so a rule could not be written at all without sight.", [.ru: "Helm работает с VoiceOver. Каждый элемент управления теперь называет себя — редактор правил состоял из кнопок и полей, не сообщавших ничего, и правило нельзя было составить вслепую.", .es: "Helm se puede usar con VoiceOver: todos los controles dicen qué son. El editor de reglas no anunciaba nada y no podía usarse sin ver la pantalla.", .fr: "Helm s’utilise avec VoiceOver : chaque contrôle dit ce qu’il est. L’éditeur de règles n’annonçait rien et ne pouvait pas être utilisé sans voir l’écran.", .de: "Helm lässt sich mit VoiceOver bedienen: Jedes Bedienelement sagt jetzt, was es ist. Der Regel-Editor kündigte nichts an und war ohne Sicht nicht bedienbar.", .ja: "VoiceOver で操作できるようになりました。すべてのコントロールが自分の役割を読み上げます。ルールエディタは何も読み上げず、目視なしでは使えませんでした。", .zh: "现在可以用旁白操作 Helm：每个控件都会说明自己是什么。此前规则编辑器不做任何朗读，看不见就无法使用。", .pt: "O Helm pode ser usado com o VoiceOver: cada controle diz o que é. O editor de regras não anunciava nada e não podia ser usado sem ver a tela."])),
                ChangeItem(kind: .fix, text: L("Nothing Helm runs can hang. Homebrew, the VPN list and the power settings are read by running the system's own tools, and a tool that was talkative enough about its own warnings could stop forever, taking the screen waiting for it with it.", [.ru: "Ничто из запускаемого Helm не зависает. Homebrew, список VPN и настройки питания читаются системными утилитами, и достаточно многословная утилита могла остановиться навсегда, забрав с собой ждавший её экран.", .es: "Nada de lo que Helm ejecuta puede colgarse. Una herramienta lo bastante verbosa en sus avisos podía detenerse para siempre y bloquear la pantalla que la esperaba.", .fr: "Rien de ce que Helm exécute ne peut se figer. Un outil suffisamment bavard sur ses avertissements pouvait s’arrêter indéfiniment et bloquer l’écran qui l’attendait.", .de: "Nichts, was Helm ausführt, kann hängen bleiben. Ein Werkzeug mit genügend eigenen Warnungen konnte für immer stehen bleiben und den wartenden Bildschirm mitnehmen.", .ja: "Helm が実行するコマンドがハングしなくなりました。警告を大量に出すツールが永久に停止し、待っている画面を巻き添えにすることがありました。", .zh: "Helm 运行的命令不会再卡死。此前某个工具若输出足够多的警告，就会永远停住，并拖住等待它的界面。", .pt: "Nada do que o Helm executa pode travar. Uma ferramenta suficientemente verbosa nos próprios avisos podia parar para sempre e levar junto a tela que a aguardava."])),
                ChangeItem(kind: .new, text: L("Autopilot shows what it did. A report of the last 30 days at the bottom of the page: which file, where it went, and which rule decided — because a folder that tidies itself is only worth trusting if it can say what it tidied.", [.ru: "Автопилот показывает, что сделал. Отчёт за последние 30 дней внизу страницы: какой файл, куда уехал и какое правило так решило, — папка, которая убирается сама, заслуживает доверия только если может рассказать, что убрала.", .es: "El piloto automático muestra lo que hizo. Un informe de los últimos 30 días: qué archivo, adónde fue y qué regla lo decidió.", .fr: "Le pilote automatique montre ce qu’il a fait. Un rapport des 30 derniers jours : quel fichier, où il est allé et quelle règle en a décidé.", .de: "Der Autopilot zeigt, was er getan hat. Ein Bericht der letzten 30 Tage: welche Datei, wohin sie ging und welche Regel das entschieden hat.", .ja: "オートパイロットが何をしたかを表示します。過去30日のレポート — どのファイルが、どこへ、どのルールで動いたか。", .zh: "自动整理会说明它做过什么。最近 30 天的报告：哪个文件、去了哪里、由哪条规则决定。", .pt: "O piloto automático mostra o que fez. Um relatório dos últimos 30 dias: qual arquivo, para onde foi e qual regra decidiu."])),
                ChangeItem(kind: .upd, text: L("A design pass over the whole app, in the macOS 26/27 idiom: Liquid Glass on the menu-bar panel, page titles that line up with the page beneath them at any window width, text that recedes without becoming unreadable, and numbers that roll instead of cutting. The sidebar groups modules into Files and Utilities rather than putting five of seven in one pile, and the window opens wide enough for the Disk screen to show everything it measures.", [.ru: "Дизайн-проход по всему приложению в стиле macOS 26/27: Liquid Glass в панели строки меню, заголовки страниц, выровненные с содержимым при любой ширине окна, приглушённый текст, который остаётся читаемым, и цифры, которые перекатываются, а не режутся. В боковом меню появились «Файлы» и «Утилиты» вместо пяти модулей из семи в одной куче, а окно открывается достаточно широким, чтобы «Диск» показывал всё, что измерил.", .es: "Un repaso de diseño de toda la app al estilo de macOS 26/27: Liquid Glass en el panel, títulos alineados con su contenido a cualquier ancho, texto atenuado que sigue siendo legible y cifras que ruedan en vez de cortarse. La barra lateral agrupa en Archivos y Utilidades.", .fr: "Une passe de design sur toute l’app, dans l’idiome macOS 26/27 : Liquid Glass dans le panneau, des titres alignés avec leur contenu à toute largeur, un texte atténué qui reste lisible et des chiffres qui défilent au lieu de sauter. La barre latérale regroupe en Fichiers et Utilitaires.", .de: "Ein Design-Durchgang durch die ganze App im macOS-26/27-Idiom: Liquid Glass im Menüleisten-Panel, Titel, die bei jeder Fensterbreite zum Inhalt darunter passen, zurückgenommener Text, der lesbar bleibt, und Zahlen, die rollen statt zu springen. Die Seitenleiste gruppiert in Dateien und Dienstprogramme.", .ja: "アプリ全体のデザインを macOS 26/27 の作法に合わせました。メニューバーパネルの Liquid Glass、どの幅でも下の内容と揃うページ見出し、読める濃さの補助テキスト、そして切り替わらず転がる数字。サイドバーは「ファイル」と「ユーティリティ」に整理されます。", .zh: "对整个应用做了一次符合 macOS 26/27 风格的设计调整：菜单栏面板采用 Liquid Glass，页面标题在任何窗口宽度下都与下方内容对齐，次要文字在变淡的同时保持可读，数字滚动而不是硬切。侧边栏按“文件”和“实用工具”分组。", .pt: "Uma passagem de design por todo o app, no idioma do macOS 26/27: Liquid Glass no painel, títulos alinhados com o conteúdo em qualquer largura, texto atenuado que continua legível e números que rolam em vez de cortar. A barra lateral agrupa em Arquivos e Utilitários."])),
                ChangeItem(kind: .upd, text: L("The disk list can be walked from the keyboard: arrow keys between rows, Return to go into a folder, ⌘↑ to come back out. And the screen now fits the width it has: on a narrow window the ring gives way to the list, which carries the same facts in less room.", [.ru: "По списку в «Диске» теперь можно ходить с клавиатуры: стрелки между строками, Return — войти в папку, ⌘↑ — вернуться. А экран подстраивается под ширину окна: когда её мало, кольцо уступает место списку — он несёт те же факты и требует меньше места.", .es: "La lista del disco se puede recorrer con el teclado: flechas entre filas, Retorno para entrar en una carpeta, ⌘↑ para volver. Y la barra superior vuelve a caber: el dato del escaneo pasó debajo del anillo.", .fr: "La liste du disque se parcourt au clavier : flèches entre les lignes, Retour pour entrer dans un dossier, ⌘↑ pour ressortir. Et la barre du haut tient à nouveau : l’info d’analyse est passée sous l’anneau.", .de: "Die Festplattenliste lässt sich per Tastatur durchgehen: Pfeiltasten zwischen Zeilen, Return in einen Ordner hinein, ⌘↑ wieder heraus. Und die Leiste darüber passt wieder — die Scan-Angabe steht jetzt unter dem Ring.", .ja: "ディスクの一覧をキーボードで操作できます。矢印キーで行を移動、Return でフォルダに入り、⌘↑ で戻ります。上のバーも収まるようになりました（スキャン情報はリングの下へ）。", .zh: "磁盘列表现在可以用键盘浏览：方向键移动，Return 进入文件夹，⌘↑ 返回上层。上方的栏也重新放得下了——扫描信息移到了环形图下方。", .pt: "A lista do disco pode ser percorrida pelo teclado: setas entre linhas, Return para entrar numa pasta, ⌘↑ para voltar. E a barra acima cabe de novo — a informação do escaneamento foi para baixo do anel."])),
                ChangeItem(kind: .upd, text: L("The disk map now answers VoiceOver: every wedge reads its name, its size and its share of the folder, and can be opened from there. Folders in the list beside it can be opened from the context menu too — the double-click still works and is no longer the only way.", [.ru: "Карта диска теперь отвечает VoiceOver: каждый сегмент называет папку, размер и её долю, и оттуда же в неё можно провалиться. Папки в списке рядом открываются и через контекстное меню — двойной клик работает по-прежнему, но перестал быть единственным способом.", .es: "El mapa del disco ahora responde a VoiceOver: cada sector dice su nombre, tamaño y porcentaje, y se puede abrir desde ahí. Las carpetas de la lista también se abren desde el menú contextual.", .fr: "La carte du disque répond désormais à VoiceOver : chaque secteur annonce son nom, sa taille et sa part, et peut être ouvert de là. Les dossiers de la liste s’ouvrent aussi via le menu contextuel.", .de: "Die Festplattenkarte antwortet jetzt VoiceOver: Jedes Segment nennt Namen, Größe und Anteil und lässt sich von dort öffnen. Ordner in der Liste daneben lassen sich auch über das Kontextmenü öffnen.", .ja: "ディスクマップが VoiceOver に応答します。各セグメントが名前・サイズ・割合を読み上げ、そこから開けます。隣のリストのフォルダはコンテキストメニューからも開けます。", .zh: "磁盘分布图现在支持 VoiceOver：每个扇区会读出名称、大小和占比，并可从那里打开。旁边列表中的文件夹也能通过右键菜单打开。", .pt: "O mapa do disco agora responde ao VoiceOver: cada setor diz seu nome, tamanho e porcentagem, e pode ser aberto dali. As pastas da lista também abrem pelo menu de contexto."])),
                ChangeItem(kind: .new, text: L("Autopilot: folders that keep themselves in order. Point Helm at a folder and give it rules — a file that arrives is checked against them in order, and the first one that matches is the one that runs. Sort by kind or by month, move, rename, tag, or bin; conditions include the site a file was downloaded from. A new rule is shown before it is switched on: the editor lists what is in the folder now and what would happen to each file. Nothing is ever overwritten, and nothing is acted on twice.", [.ru: "«Автопилот»: папки, которые держат себя в порядке сами. Укажите Helm папку и задайте правила — появившийся файл проверяется по ним по порядку, и срабатывает первое подошедшее. Разложить по видам или по месяцам, переместить, переименовать, пометить тегом или отправить в Корзину; среди условий есть сайт, откуда файл скачан. Новое правило показывают до включения: редактор перечисляет, что сейчас лежит в папке и что с чем произойдёт. Ничего никогда не перезаписывается, и ничто не обрабатывается дважды.", .es: "Piloto automático: carpetas que se mantienen en orden solas. Elige una carpeta y dale reglas — un archivo que llega se comprueba en orden y se ejecuta la primera que coincide. Ordenar por tipo o por mes, mover, renombrar, etiquetar o enviar a la Papelera. Una regla nueva se muestra antes de activarse: el editor lista lo que hay ahora y qué pasaría con cada archivo.", .fr: "Pilote automatique : des dossiers qui se tiennent en ordre tout seuls. Désignez un dossier et donnez-lui des règles — un fichier qui arrive est vérifié dans l’ordre et la première qui correspond s’exécute. Ranger par type ou par mois, déplacer, renommer, étiqueter ou mettre à la corbeille. Une nouvelle règle est montrée avant d’être activée.", .de: "Autopilot: Ordner, die sich selbst in Ordnung halten. Wähle einen Ordner und gib ihm Regeln — eine ankommende Datei wird der Reihe nach geprüft, und die erste passende läuft. Nach Art oder Monat sortieren, bewegen, umbenennen, taggen oder in den Papierkorb. Eine neue Regel wird vor dem Einschalten gezeigt.", .ja: "「オートパイロット」: 自分で整った状態を保つフォルダ。フォルダを指定してルールを与えると、届いたファイルが上から順に照合され、最初に一致したものが実行されます。種類別・月別の整理、移動、名前変更、タグ付け、ゴミ箱へ。新しいルールは有効にする前に、いま何がどうなるかを一覧で示します。", .zh: "“自动驾驶”：会自己保持整齐的文件夹。指定一个文件夹并设定规则，新到的文件按顺序检查，第一条匹配的规则执行。按种类或月份归类、移动、重命名、加标签或移到废纸篓。新规则在开启前先展示：编辑器会列出文件夹里现在有什么、每个文件会发生什么。", .pt: "Piloto automático: pastas que se mantêm em ordem sozinhas. Aponte para uma pasta e dê regras a ela — um arquivo que chega é verificado na ordem e a primeira que casa é a que roda. Organizar por tipo ou por mês, mover, renomear, etiquetar ou mandar para o Lixo. Uma regra nova é mostrada antes de ser ligada."])),
                ChangeItem(kind: .new, text: L("The duplicate finder is its own screen now, right after Disk. It used to search whatever folder the ring happened to be showing, so you could only look where you had already scanned; now you point it at a folder and it remembers it. It still compares content rather than names, still keeps one copy of every group, and still never offers a hard link.", [.ru: "Поиск дубликатов теперь отдельный экран, сразу после «Диска». Раньше он искал в той папке, которую показывало кольцо, — то есть только там, где вы уже сканировали. Теперь вы сами указываете папку, и он её запоминает. Содержимое по-прежнему сравнивается вместо имён, одна копия в каждой группе остаётся, а жёсткие ссылки не предлагаются.", .es: "El buscador de duplicados es ahora una pantalla propia, justo después de Disco. Antes buscaba en la carpeta que mostraba el anillo; ahora eliges la carpeta y la recuerda. Sigue comparando contenido y no nombres, y siempre conserva una copia.", .fr: "Le chercheur de doublons a son propre écran, juste après Disque. Il cherchait dans le dossier affiché par l’anneau ; désormais vous désignez le dossier et il s’en souvient. Il compare toujours le contenu, pas les noms, et garde toujours une copie.", .de: "Die Duplikatsuche hat einen eigenen Bereich, direkt nach Festplatte. Bisher durchsuchte sie den Ordner, den gerade der Ring zeigte; jetzt wählst du den Ordner, und sie merkt ihn sich. Verglichen wird weiter der Inhalt statt der Namen, und eine Kopie bleibt immer.", .ja: "重複ファイル検索が独立した画面になり、「ディスク」の次に並びます。これまではリングが表示中のフォルダしか調べられませんでしたが、これからは自分でフォルダを指定でき、次回も覚えています。名前ではなく内容を比較し、各グループの 1 つは必ず残します。", .zh: "重复文件查找现在是独立的一页，紧跟在“磁盘”之后。过去它只能搜索环形图当前显示的文件夹，现在由你指定文件夹，并且会记住。仍然比较内容而非文件名，每组也仍然保留一份。", .pt: "O buscador de duplicatas agora é uma tela própria, logo depois de Disco. Antes ele procurava na pasta que o anel mostrava; agora você escolhe a pasta e ele a memoriza. Continua comparando conteúdo em vez de nomes e sempre mantém uma cópia."])),
                ChangeItem(kind: .upd, text: L("Keyboard now fixes short words. Words of two or three letters were left alone on purpose — a spell checker will call almost any pair of letters a word, so asking one was worse than not asking. The most common mistyped words are exactly that short, so Helm now knows a list of them by heart and converts only when it recognises the result and does not recognise what you typed.", [.ru: "«Клавиатура» теперь исправляет короткие слова. Слова из двух-трёх букв намеренно не трогались: словарь назовёт словом почти любую пару букв, так что спрашивать его было хуже, чем не спрашивать. Но именно такие слова чаще всего и набирают не в той раскладке — теперь Helm знает список таких слов наизусть и меняет раскладку, только если узнаёт результат и не узнаёт набранное.", .es: "Teclado ahora corrige palabras cortas. Las de dos o tres letras se dejaban intactas a propósito: un corrector llama palabra a casi cualquier par de letras. Helm se sabe de memoria una lista de las más comunes y solo convierte si reconoce el resultado y no lo escrito.", .fr: "Clavier corrige désormais les mots courts. Ceux de deux ou trois lettres étaient laissés de côté exprès : un correcteur accepte presque n’importe quelle paire de lettres. Helm connaît par cœur une liste des plus courants et ne convertit que s’il reconnaît le résultat et pas ce qui a été tapé.", .de: "Tastatur korrigiert jetzt auch kurze Wörter. Zwei- und dreibuchstabige blieben absichtlich unangetastet: Eine Rechtschreibprüfung hält fast jedes Buchstabenpaar für ein Wort. Helm kennt eine Liste der häufigsten auswendig und wandelt nur um, wenn es das Ergebnis kennt und das Getippte nicht.", .ja: "「キーボード」が短い単語も直します。2〜3 文字の語はあえて対象外でした。スペルチェッカーはほとんどどんな 2 文字も単語と答えてしまうからです。誤った配列で打たれるのはまさにそういう語なので、Helm は代表的な語のリストを覚え、変換後を知っていて入力を知らないときだけ変換します。", .zh: "“键盘”现在也能修正短词。两三个字母的词此前被刻意跳过：拼写检查几乎会把任何字母组合都算作单词，问它还不如不问。而最常打错布局的恰恰是这些短词，因此 Helm 直接记住了一份常用短词表，只有当它认得转换结果、又不认得你输入的内容时才会转换。", .pt: "O Teclado agora corrige palavras curtas. As de duas ou três letras eram deixadas de lado de propósito: um corretor chama de palavra quase qualquer par de letras. O Helm sabe de cor uma lista das mais comuns e só converte quando reconhece o resultado e não reconhece o que foi digitado."])),
                ChangeItem(kind: .fix, text: L("When a file will not move, Helm now says why on every screen that removes things. Disk and the duplicate finder used to give you a count and leave you to guess — usually the answer was Full Disk Access, which is one click away once you know. Quiet text is also readable again: the captions and secondary lines were fainter than they were meant to be.", [.ru: "Когда файл не удаётся переместить, Helm теперь говорит почему — на каждом экране, где что-то удаляется. «Диск» и поиск дубликатов раньше показывали число и оставляли догадываться; чаще всего дело в доступе к диску, а это один клик, если знать. И приглушённый текст снова читается: подписи и второстепенные строки были бледнее, чем задумано.", .es: "Cuando un archivo no se puede mover, Helm ahora dice por qué en todas las pantallas que eliminan. Disco y el buscador de duplicados solo daban un número; casi siempre la causa es el Acceso total al disco. Además, el texto atenuado vuelve a leerse bien.", .fr: "Quand un fichier refuse de bouger, Helm dit maintenant pourquoi, sur chaque écran qui supprime. Disque et le chercheur de doublons ne donnaient qu’un nombre ; la cause est presque toujours l’accès complet au disque. Et le texte atténué redevient lisible.", .de: "Wenn sich eine Datei nicht verschieben lässt, sagt Helm jetzt auf jedem Bildschirm, der entfernt, warum. Festplatte und die Duplikatsuche nannten nur eine Zahl; meist ist Festplattenvollzugriff die Antwort. Außerdem ist zurückgenommener Text wieder lesbar.", .ja: "ファイルを移動できなかったとき、削除を行うすべての画面で理由を示すようになりました。「ディスク」と重複ファイル検索は件数だけを出していましたが、多くはフルディスクアクセスが原因です。控えめな文字の濃さも読める値に戻しました。", .zh: "当文件无法移动时，Helm 现在会在每个执行删除的页面说明原因。“磁盘”和重复文件查找过去只给一个数字，而答案通常是完全磁盘访问权限。次要文字的深浅也调回了可读的程度。", .pt: "Quando um arquivo não sai do lugar, o Helm agora diz por quê em todas as telas que removem. Disco e o buscador de duplicatas davam só um número; quase sempre a causa é o Acesso Total ao Disco. E o texto atenuado voltou a ser legível."])),
                ChangeItem(kind: .fix, text: L("The disk ring was measuring the wrong thing when you scanned a folder: it drew the volume's free space alongside the folder's contents, so a small folder came out as a blank grey circle. And \u{201C}Scan again\u{201D} now scans the same place again instead of sending you back to the volume list. In the duplicate finder, files that refused to move stay ticked, so you can fix the reason and try again without starting over. Homebrew search puts the name you typed first.", [.ru: "Кольцо «Диска» мерило не то, когда вы сканировали папку: рядом с содержимым оно рисовало свободное место всего тома, и небольшая папка выходила пустым серым кругом. А «Сканировать заново» теперь и правда сканирует то же самое место, а не возвращает к списку томов. В поиске дубликатов файлы, которые не удалось переместить, остаются отмеченными — можно устранить причину и повторить, не начиная заново. Поиск в Homebrew ставит первым то имя, которое вы набрали.", .es: "El anillo del disco medía lo que no debía al escanear una carpeta: dibujaba el espacio libre del volumen junto al contenido, y una carpeta pequeña salía como un círculo gris vacío. «Escanear de nuevo» ahora escanea el mismo sitio. En duplicados, los archivos que no se pudieron mover siguen marcados. La búsqueda de Homebrew pone primero el nombre que escribiste.", .fr: "L\u{2019}anneau du disque mesurait la mauvaise chose lors de l\u{2019}analyse d\u{2019}un dossier : il dessinait l\u{2019}espace libre du volume à côté du contenu, et un petit dossier devenait un cercle gris vide. « Réanalyser » réanalyse maintenant le même endroit. Dans les doublons, les fichiers refusés restent cochés. La recherche Homebrew place en tête le nom que vous avez tapé.", .de: "Der Festplattenring maß beim Scannen eines Ordners das Falsche: Er zeichnete den freien Platz des Volumes neben den Inhalt, und ein kleiner Ordner wurde zu einem leeren grauen Kreis. «Erneut scannen» scannt jetzt dieselbe Stelle. In der Duplikatsuche bleiben abgelehnte Dateien angehakt. Die Homebrew-Suche stellt den getippten Namen nach vorn.", .ja: "フォルダをスキャンしたとき、ディスクのリングは中身と一緒にボリュームの空き容量まで描いていたため、小さなフォルダはただの灰色の円になっていました。「再スキャン」は同じ場所をもう一度測るようになりました。重複ファイル検索では、移動できなかったファイルのチェックが残ります。Homebrew の検索は入力した名前を先頭に出します。", .zh: "扫描文件夹时，磁盘环把整个卷的可用空间和文件夹内容画在一起，小文件夹就成了一个空白的灰圈。“重新扫描”现在会重新扫描同一位置。重复文件查找中，未能移动的文件保持勾选。Homebrew 搜索会把你输入的名称排在最前。", .pt: "O anel do disco media a coisa errada ao escanear uma pasta: desenhava o espaço livre do volume junto ao conteúdo, e uma pasta pequena virava um círculo cinza vazio. «Escanear de novo» agora escaneia o mesmo lugar. Nas duplicatas, os arquivos recusados continuam marcados. A busca do Homebrew coloca primeiro o nome que você digitou."])),
                ChangeItem(kind: .upd, text: L("Autopilot's preview now says where each file would land, not only what would be done to it. And About shows both badges that apply: the program is in beta, and this copy is on the dev channel.", [.ru: "Превью «Автопилота» теперь говорит, куда именно уедет каждый файл, а не только что с ним будет. А в «О Helm» видны оба шильдика: программа в бете, и эта копия — на канале dev.", .es: "La vista previa del Piloto automático dice ahora dónde acabaría cada archivo, no solo qué se le haría. Y «Acerca de» muestra las dos insignias que aplican.", .fr: "L\u{2019}aperçu du Pilote automatique indique désormais où chaque fichier atterrirait, pas seulement ce qui lui arriverait. Et « À propos » affiche les deux badges qui s\u{2019}appliquent.", .de: "Die Vorschau des Autopiloten sagt jetzt, wo jede Datei landen würde, nicht nur, was mit ihr geschieht. Und «Über» zeigt beide zutreffenden Badges.", .ja: "「オートパイロット」のプレビューが、何をするかだけでなく、どこに置かれるかも示すようになりました。「Helm について」には当てはまる 2 つのバッジが並びます。", .zh: "“自动驾驶”的预览现在会说明每个文件会落到哪里，而不只是会发生什么。“关于 Helm”同时显示两个适用的标签。", .pt: "A prévia do Piloto automático agora diz onde cada arquivo cairia, não só o que aconteceria com ele. E «Sobre» mostra os dois selos que se aplicam."])),
                ChangeItem(kind: .fix, text: L("If the folder Helm last measured has since been deleted, Disk no longer opens on an empty screen with no explanation — it takes you back to the volume list. An empty folder now says it is empty instead of showing nothing.", [.ru: "Если папку, которую Helm мерил в прошлый раз, с тех пор удалили, «Диск» больше не открывается пустым экраном без объяснений — он возвращает к списку томов. А пустая папка теперь так и говорит, вместо того чтобы показывать пустоту.", .es: "Si la carpeta que el Helm midió por última vez se ha borrado, Disco ya no abre una pantalla vacía sin explicación: te lleva a la lista de volúmenes. Una carpeta vacía ahora lo dice.", .fr: "Si le dossier mesuré la dernière fois a été supprimé depuis, Disque n\u{2019}ouvre plus un écran vide sans explication : il ramène à la liste des volumes. Un dossier vide le dit maintenant.", .de: "Wurde der zuletzt gemessene Ordner inzwischen gelöscht, öffnet Festplatte nicht mehr einen leeren Bildschirm ohne Erklärung, sondern führt zurück zur Volume-Liste. Ein leerer Ordner sagt das jetzt auch.", .ja: "前回測ったフォルダがその後削除されていた場合、「ディスク」は説明のない空白画面ではなくボリューム一覧に戻ります。空のフォルダは空だと表示します。", .zh: "如果上次测量的文件夹已被删除，“磁盘”不再打开一个没有说明的空白页面，而是回到卷列表。空文件夹现在会说明自己是空的。", .pt: "Se a pasta medida da última vez foi apagada desde então, o Disco não abre mais uma tela vazia sem explicação — leva de volta à lista de volumes. Uma pasta vazia agora diz que está vazia."])),
                ChangeItem(kind: .upd, text: L("Keyboard is one gesture now. Tap the key — right ⌘ unless you change it — and Helm fixes what is in front of you: the selected text if there is any, otherwise the last word, and tapping again puts it back. There were five shortcuts to set up and none of them was set. Any modifier can be the key — right or left — and on Macs with a 🌐︎ key, that too. Transliteration and changing case are gone: transliteration could not be undone reliably, and macOS already changes case in the Edit menu.", [.ru: "«Клавиатура» теперь — один жест. Нажали клавишу (по умолчанию правую ⌘) — Helm исправляет то, что перед вами: выделенный текст, если он есть, иначе последнее слово; повторное нажатие возвращает. Раньше нужно было настроить пять сочетаний, и ни одно не было задано. Клавишей может быть любой модификатор — правый или левый, — а на маках с 🌐︎ и она. Транслитерация и смена регистра убраны: транслитерацию нельзя было надёжно отменить, а регистр macOS меняет сама — в меню «Правка».", .es: "El Teclado es ahora un solo gesto. Pulsa la tecla (⌘ derecha por defecto) y Helm corrige lo que tienes delante: la selección si la hay, si no la última palabra; púlsala otra vez y lo devuelve. Antes había cinco atajos que configurar y ninguno estaba puesto. La transliteración y el cambio de mayúsculas se han quitado.", .fr: "Le Clavier tient en un geste. Appuyez sur la touche (⌘ droite par défaut) et Helm corrige ce qui est devant vous : la sélection s\u{2019}il y en a une, sinon le dernier mot ; une seconde pression le restaure. Il y avait cinq raccourcis à régler et aucun ne l\u{2019}était. La translittération et le changement de casse sont retirés.", .de: "Die Tastatur ist jetzt eine Geste. Tippe die Taste (standardmäßig rechte ⌘) und Helm korrigiert, was vor dir ist: die Auswahl, sonst das letzte Wort — noch einmal stellt es zurück. Vorher waren fünf Kurzbefehle einzurichten und keiner war gesetzt. Transliteration und Groß-/Kleinschreibung entfallen.", .ja: "「キーボード」はひとつの操作になりました。キー（既定では右 ⌘）を叩くと、目の前にあるものを直します。選択範囲があればそれを、なければ直前の単語を。もう一度叩けば元に戻ります。以前は 5 つのショートカットを設定する必要があり、どれも未設定でした。ローマ字化と大文字小文字の変換はなくなりました。", .zh: "“键盘”现在只有一个手势。敲一下按键（默认右 ⌘），Helm 就修正你眼前的东西：有选中文本就改选区，否则改上一个词，再敲一次还原。此前要设置五个快捷键，而且一个都没设。转写和改变大小写已移除。", .pt: "O Teclado agora é um gesto só. Toque a tecla (⌘ direita por padrão) e o Helm corrige o que está à sua frente: a seleção, se houver; caso contrário, a última palavra — e tocar de novo desfaz. Antes eram cinco atalhos para configurar e nenhum estava definido. Transliteração e mudança de maiúsculas foram removidas."])),
                ChangeItem(kind: .new, text: L("Abbreviations. A short token you type often and what it stands for, expanded at the same word boundary a layout conversion happens at. A word that expanded is never also converted. And optionally the one typing habit Helm is sure enough about to correct: \u{201C}ПРivet\u{201D} → \u{201C}Privet\u{201D} — never a word typed in capitals on purpose, and never one with a digit in it.", [.ru: "Аббревиатуры. Короткое сочетание, которое вы часто набираете, и то, во что оно разворачивается, — на той же границе слова, где происходит смена раскладки. Развернувшееся слово не переводится ещё и в другую раскладку. И, по желанию, единственная опечатка, в которой Helm уверен достаточно, чтобы её исправлять: «ПРивет» → «Привет» — но никогда «ПРИВЕТ» (кто-то кричит намеренно) и никогда слово с цифрой (это идентификатор).", .es: "Abreviaturas. Un texto corto que escribes a menudo y aquello en lo que se expande, en el mismo límite de palabra donde ocurre la conversión de distribución. Una palabra expandida ya no se convierte además. Y, opcionalmente, la única errata que Helm corrige con confianza: «HOla» → «Hola», nunca una palabra escrita en mayúsculas a propósito ni una con un dígito.", .fr: "Abréviations. Un raccourci que vous tapez souvent et ce qu’il devient, à la même limite de mot que la conversion de disposition. Un mot développé n’est jamais converti en plus. Et, en option, la seule faute de frappe que Helm corrige sans hésiter : « BOnjour » → « Bonjour » — jamais un mot en capitales voulu, jamais un mot contenant un chiffre.", .de: "Abkürzungen. Ein kurzes Kürzel, das du oft tippst, und wofür es steht — an derselben Wortgrenze, an der auch die Belegung umgeschaltet wird. Ein aufgelöstes Kürzel wird nicht zusätzlich umgewandelt. Und auf Wunsch der eine Tippfehler, bei dem Helm sicher genug ist: „HAllo“ → „Hallo“ — nie ein absichtlich groß geschriebenes Wort und nie eines mit einer Ziffer.", .ja: "略語展開。よく打つ短いつづりと、その展開先を登録できます。展開は配列変換と同じ語の区切りで起こり、展開された語がさらに変換されることはありません。さらに任意で、Helm が確信を持てる唯一の打ち間違いも直します: 「KOnnichiwa」→「Konnichiwa」。わざとの全大文字や、数字を含む語は対象外です。", .zh: "缩写展开。把常打的短写和它代表的内容对应起来，在与布局转换相同的词边界展开。已展开的词不会再被转换。还可选修正 Helm 有把握的那一类手误：“NIhao” → “Nihao”——不动故意全大写的词，也不动含数字的词。", .pt: "Abreviações. Um atalho curto que você digita com frequência e aquilo em que ele se expande, no mesmo limite de palavra em que acontece a conversão de layout. Uma palavra expandida nunca é também convertida. E, opcionalmente, o único erro de digitação que o Helm corrige com segurança: «OLá» → «Olá» — nunca uma palavra em maiúsculas de propósito, nem uma com dígito."])),
                ChangeItem(kind: .fix, text: L("Removing an app no longer offers another app\u{2019}s files. Leftovers were matched by the start of a bundle id and never checked against what is installed, so uninstalling one app could arrive with a still-installed neighbour\u{2019}s data already ticked.", [.ru: "\u{0423}\u{0434}\u{0430}\u{043B}\u{0435}\u{043D}\u{0438}\u{0435} \u{043F}\u{0440}\u{0438}\u{043B}\u{043E}\u{0436}\u{0435}\u{043D}\u{0438}\u{044F} \u{0431}\u{043E}\u{043B}\u{044C}\u{0448}\u{0435} \u{043D}\u{0435} \u{043F}\u{0440}\u{0435}\u{0434}\u{043B}\u{0430}\u{0433}\u{0430}\u{0435}\u{0442} \u{0444}\u{0430}\u{0439}\u{043B}\u{044B} \u{0447}\u{0443}\u{0436}\u{043E}\u{0433}\u{043E}. \u{041E}\u{0441}\u{0442}\u{0430}\u{0442}\u{043A}\u{0438} \u{0438}\u{0441}\u{043A}\u{0430}\u{043B}\u{0438}\u{0441}\u{044C} \u{043F}\u{043E} \u{043D}\u{0430}\u{0447}\u{0430}\u{043B}\u{0443} bundle id \u{0438} \u{043D}\u{0435} \u{0441}\u{0432}\u{0435}\u{0440}\u{044F}\u{043B}\u{0438}\u{0441}\u{044C} \u{0441} \u{0442}\u{0435}\u{043C}, \u{0447}\u{0442}\u{043E} \u{0443}\u{0441}\u{0442}\u{0430}\u{043D}\u{043E}\u{0432}\u{043B}\u{0435}\u{043D}\u{043E}, \u{0438} \u{0434}\u{0430}\u{043D}\u{043D}\u{044B}\u{0435} \u{0441}\u{043E}\u{0441}\u{0435}\u{0434}\u{0430} \u{043C}\u{043E}\u{0433}\u{043B}\u{0438} \u{043F}\u{0440}\u{0438}\u{0439}\u{0442}\u{0438} \u{0443}\u{0436}\u{0435} \u{043E}\u{0442}\u{043C}\u{0435}\u{0447}\u{0435}\u{043D}\u{043D}\u{044B}\u{043C}\u{0438}.", .es: "Desinstalar una app ya no ofrece archivos de otra. Los restos se buscaban por el principio del bundle id y no se compraban con lo instalado.", .fr: "D\u{00E9}sinstaller une app ne propose plus les fichiers d\u{2019}une autre. Les restes \u{00E9}taient trouv\u{00E9}s par le d\u{00E9}but du bundle id, sans v\u{00E9}rifier ce qui est install\u{00E9}.", .de: "Das Entfernen einer App bietet keine Dateien einer anderen mehr an. Reste wurden am Anfang der Bundle-ID erkannt, ohne Abgleich mit dem, was installiert ist.", .ja: "\u{30A2}\u{30D7}\u{30EA}\u{306E}\u{524A}\u{9664}\u{6642}\u{306B}\u{3001}\u{5225}\u{306E}\u{30A2}\u{30D7}\u{30EA}\u{306E}\u{30D5}\u{30A1}\u{30A4}\u{30EB}\u{3092}\u{63D0}\u{6848}\u{3057}\u{306A}\u{304F}\u{306A}\u{308A}\u{307E}\u{3057}\u{305F}\u{3002}", .zh: "\u{5378}\u{8F7D}\u{4E00}\u{4E2A}\u{5E94}\u{7528}\u{4E0D}\u{4F1A}\u{518D}\u{5217}\u{51FA}\u{53E6}\u{4E00}\u{4E2A}\u{5E94}\u{7528}\u{7684}\u{6587}\u{4EF6}\u{3002}", .pt: "Remover um app n\u{00E3}o oferece mais arquivos de outro. Os restos eram encontrados pelo in\u{00ED}cio do bundle id, sem conferir o que est\u{00E1} instalado."])),
                ChangeItem(kind: .fix, text: L("Autopilot stops sinking files on a USB stick. Sorting into a subfolder used the file\u{2019}s current parent, so on a disk that cannot carry Helm\u{2019}s \u{201C}already done\u{201D} mark every sweep sorted the result again. A rule with nowhere to move to can no longer be switched on.", [.ru: "\u{0410}\u{0432}\u{0442}\u{043E}\u{043F}\u{0438}\u{043B}\u{043E}\u{0442} \u{0431}\u{043E}\u{043B}\u{044C}\u{0448}\u{0435} \u{043D}\u{0435} \u{0437}\u{0430}\u{043A}\u{0430}\u{043F}\u{044B}\u{0432}\u{0430}\u{0435}\u{0442} \u{0444}\u{0430}\u{0439}\u{043B}\u{044B} \u{043D}\u{0430} \u{0444}\u{043B}\u{0435}\u{0448}\u{043A}\u{0435}. \u{0420}\u{0430}\u{0441}\u{043A}\u{043B}\u{0430}\u{0434}\u{043A}\u{0430} \u{043F}\u{043E} \u{043F}\u{043E}\u{0434}\u{043F}\u{0430}\u{043F}\u{043A}\u{0430}\u{043C} \u{0441}\u{0447}\u{0438}\u{0442}\u{0430}\u{043B}\u{0430}\u{0441}\u{044C} \u{043E}\u{0442} \u{0442}\u{0435}\u{043A}\u{0443}\u{0449}\u{0435}\u{0439} \u{043F}\u{0430}\u{043F}\u{043A}\u{0438} \u{0444}\u{0430}\u{0439}\u{043B}\u{0430}, \u{0438} \u{043D}\u{0430} \u{0434}\u{0438}\u{0441}\u{043A}\u{0435}, \u{043A}\u{043E}\u{0442}\u{043E}\u{0440}\u{044B}\u{0439} \u{043D}\u{0435} \u{0434}\u{0435}\u{0440}\u{0436}\u{0438}\u{0442} \u{043C}\u{0435}\u{0442}\u{043A}\u{0443} \u{00AB}\u{0443}\u{0436}\u{0435} \u{0441}\u{0434}\u{0435}\u{043B}\u{0430}\u{043D}\u{043E}\u{00BB}, \u{043A}\u{0430}\u{0436}\u{0434}\u{044B}\u{0439} \u{043F}\u{0440}\u{043E}\u{0445}\u{043E}\u{0434} \u{0440}\u{0430}\u{0441}\u{043A}\u{043B}\u{0430}\u{0434}\u{044B}\u{0432}\u{0430}\u{043B} \u{0440}\u{0435}\u{0437}\u{0443}\u{043B}\u{044C}\u{0442}\u{0430}\u{0442} \u{0437}\u{0430}\u{043D}\u{043E}\u{0432}\u{043E}. \u{041F}\u{0440}\u{0430}\u{0432}\u{0438}\u{043B}\u{043E} \u{0431}\u{0435}\u{0437} \u{043F}\u{0430}\u{043F}\u{043A}\u{0438} \u{043D}\u{0430}\u{0437}\u{043D}\u{0430}\u{0447}\u{0435}\u{043D}\u{0438}\u{044F} \u{0442}\u{0435}\u{043F}\u{0435}\u{0440}\u{044C} \u{043D}\u{0435}\u{043B}\u{044C}\u{0437}\u{044F} \u{0432}\u{043A}\u{043B}\u{044E}\u{0447}\u{0438}\u{0442}\u{044C}.", .es: "El piloto autom\u{00E1}tico deja de hundir archivos en una memoria USB, y una regla sin destino ya no puede activarse.", .fr: "Le pilote automatique n\u{2019}enfonce plus les fichiers sur une cl\u{00E9} USB, et une r\u{00E8}gle sans destination ne peut plus \u{00EA}tre activ\u{00E9}e.", .de: "Der Autopilot vergr\u{00E4}bt Dateien auf einem USB-Stick nicht mehr, und eine Regel ohne Ziel l\u{00E4}sst sich nicht mehr einschalten.", .ja: "USB \u{30E1}\u{30E2}\u{30EA}\u{4E0A}\u{3067}\u{30D5}\u{30A1}\u{30A4}\u{30EB}\u{304C}\u{6BCE}\u{56DE}\u{6DF1}\u{304F}\u{57CB}\u{3082}\u{308C}\u{308B}\u{554F}\u{984C}\u{3092}\u{4FEE}\u{6B63}\u{3002}\u{79FB}\u{52D5}\u{5148}\u{306E}\u{306A}\u{3044}\u{30EB}\u{30FC}\u{30EB}\u{306F}\u{6709}\u{52B9}\u{306B}\u{3067}\u{304D}\u{307E}\u{305B}\u{3093}\u{3002}", .zh: "\u{4FEE}\u{6B63}\u{4E86}\u{6587}\u{4EF6}\u{5728} U \u{76D8}\u{4E0A}\u{88AB}\u{9010}\u{5C42}\u{57CB}\u{6DF1}\u{7684}\u{95EE}\u{9898}\u{FF1B}\u{6CA1}\u{6709}\u{76EE}\u{6807}\u{6587}\u{4EF6}\u{5939}\u{7684}\u{89C4}\u{5219}\u{4E0D}\u{80FD}\u{518D}\u{5F00}\u{542F}\u{3002}", .pt: "O piloto autom\u{00E1}tico n\u{00E3}o afunda mais arquivos num pendrive, e uma regra sem destino n\u{00E3}o pode mais ser ligada."])),
                ChangeItem(kind: .fix, text: L("The Keyboard gesture no longer undoes at the wrong place. After an arrow key the caret is somewhere else, and the gesture retyped the word there.", [.ru: "\u{0416}\u{0435}\u{0441}\u{0442} \u{00AB}\u{041A}\u{043B}\u{0430}\u{0432}\u{0438}\u{0430}\u{0442}\u{0443}\u{0440}\u{044B}\u{00BB} \u{0431}\u{043E}\u{043B}\u{044C}\u{0448}\u{0435} \u{043D}\u{0435} \u{043E}\u{0442}\u{043A}\u{0430}\u{0442}\u{044B}\u{0432}\u{0430}\u{0435}\u{0442} \u{043D}\u{0435} \u{0432} \u{0442}\u{043E}\u{043C} \u{043C}\u{0435}\u{0441}\u{0442}\u{0435}: \u{043F}\u{043E}\u{0441}\u{043B}\u{0435} \u{0441}\u{0442}\u{0440}\u{0435}\u{043B}\u{043A}\u{0438} \u{043A}\u{0430}\u{0440}\u{0435}\u{0442}\u{043A}\u{0430} \u{0443}\u{0436}\u{0435} \u{0434}\u{0440}\u{0443}\u{0433}\u{0430}\u{044F}, \u{0430} \u{0441}\u{043B}\u{043E}\u{0432}\u{043E} \u{043D}\u{0430}\u{0431}\u{0438}\u{0440}\u{0430}\u{043B}\u{043E}\u{0441}\u{044C} \u{0442}\u{0430}\u{043C}.", .es: "El gesto del Teclado ya no deshace en el sitio equivocado despu\u{00E9}s de mover el cursor con una flecha.", .fr: "Le geste du Clavier n\u{2019}annule plus au mauvais endroit apr\u{00E8}s une touche fl\u{00E9}ch\u{00E9}e.", .de: "Die Tastatur-Geste macht nach einer Pfeiltaste nicht mehr an der falschen Stelle r\u{00FC}ckg\u{00E4}ngig.", .ja: "\u{77E2}\u{5370}\u{30AD}\u{30FC}\u{306E}\u{5F8C}\u{306B}\u{9055}\u{3046}\u{4F4D}\u{7F6E}\u{3067}\u{5143}\u{306B}\u{623B}\u{3055}\u{306A}\u{304F}\u{306A}\u{308A}\u{307E}\u{3057}\u{305F}\u{3002}", .zh: "\u{6309}\u{8FC7}\u{65B9}\u{5411}\u{952E}\u{540E}\u{FF0C}\u{952E}\u{76D8}\u{624B}\u{52BF}\u{4E0D}\u{4F1A}\u{518D}\u{5728}\u{9519}\u{8BEF}\u{7684}\u{4F4D}\u{7F6E}\u{64A4}\u{9500}\u{3002}", .pt: "O gesto do Teclado n\u{00E3}o desfaz mais no lugar errado depois de uma tecla de seta."])),
                ChangeItem(kind: .fix, text: L("Stop stops the disk scan. Opening a folder mid-scan used to start a second one that took over, leaving the first walking the disk with nothing able to stop it and the ring flickering between the two. And the duplicate finder\u{2019}s \u{201C}freed\u{201D} figure now counts the copies that actually leave.", [.ru: "\u{041A}\u{043D}\u{043E}\u{043F}\u{043A}\u{0430} \u{043E}\u{0441}\u{0442}\u{0430}\u{043D}\u{043E}\u{0432}\u{043A}\u{0438} \u{0434}\u{0435}\u{0439}\u{0441}\u{0442}\u{0432}\u{0438}\u{0442}\u{0435}\u{043B}\u{044C}\u{043D}\u{043E} \u{043E}\u{0441}\u{0442}\u{0430}\u{043D}\u{0430}\u{0432}\u{043B}\u{0438}\u{0432}\u{0430}\u{0435}\u{0442} \u{0441}\u{043A}\u{0430}\u{043D}. \u{041F}\u{0435}\u{0440}\u{0435}\u{0445}\u{043E}\u{0434} \u{0432} \u{043F}\u{0430}\u{043F}\u{043A}\u{0443} \u{043F}\u{043E}\u{0441}\u{0440}\u{0435}\u{0434}\u{0438} \u{0441}\u{043A}\u{0430}\u{043D}\u{0430} \u{0437}\u{0430}\u{043F}\u{0443}\u{0441}\u{043A}\u{0430}\u{043B} \u{0432}\u{0442}\u{043E}\u{0440}\u{043E}\u{0439}, \u{0438} \u{043F}\u{0435}\u{0440}\u{0432}\u{044B}\u{0439} \u{043E}\u{0441}\u{0442}\u{0430}\u{0432}\u{0430}\u{043B}\u{0441}\u{044F} \u{0445}\u{043E}\u{0434}\u{0438}\u{0442}\u{044C} \u{043F}\u{043E} \u{0434}\u{0438}\u{0441}\u{043A}\u{0443} \u{0431}\u{0435}\u{0437} \u{0432}\u{043E}\u{0437}\u{043C}\u{043E}\u{0436}\u{043D}\u{043E}\u{0441}\u{0442}\u{0438} \u{0435}\u{0433}\u{043E} \u{043F}\u{0440}\u{0435}\u{0440}\u{0432}\u{0430}\u{0442}\u{044C}. \u{0410} \u{0432} \u{0434}\u{0443}\u{0431}\u{043B}\u{0438}\u{043A}\u{0430}\u{0442}\u{0430}\u{0445} \u{00AB}\u{043E}\u{0441}\u{0432}\u{043E}\u{0431}\u{043E}\u{0434}\u{0438}\u{0442}\u{0441}\u{044F}\u{00BB} \u{0442}\u{0435}\u{043F}\u{0435}\u{0440}\u{044C} \u{0441}\u{0447}\u{0438}\u{0442}\u{0430}\u{0435}\u{0442} \u{0438}\u{043C}\u{0435}\u{043D}\u{043D}\u{043E} \u{0442}\u{0435} \u{043A}\u{043E}\u{043F}\u{0438}\u{0438}, \u{043A}\u{043E}\u{0442}\u{043E}\u{0440}\u{044B}\u{0435} \u{0443}\u{0439}\u{0434}\u{0443}\u{0442}.", .es: "Detener detiene el escaneo del disco, y la cifra de espacio liberado en duplicados cuenta las copias que se van.", .fr: "Arr\u{00EA}ter arr\u{00EA}te l\u{2019}analyse du disque, et l\u{2019}espace lib\u{00E9}r\u{00E9} des doublons compte les copies qui partent.", .de: "Stopp stoppt den Festplatten-Scan, und die freigegebene Gr\u{00F6}\u{00DF}e bei Duplikaten z\u{00E4}hlt die Kopien, die gehen.", .ja: "\u{505C}\u{6B62}\u{304C}\u{30C7}\u{30A3}\u{30B9}\u{30AF}\u{30B9}\u{30AD}\u{30E3}\u{30F3}\u{3092}\u{78BA}\u{5B9F}\u{306B}\u{6B62}\u{3081}\u{307E}\u{3059}\u{3002}\u{91CD}\u{8907}\u{306E}\u{300C}\u{7A7A}\u{304D}\u{5BB9}\u{91CF}\u{300D}\u{306F}\u{5B9F}\u{969B}\u{306B}\u{6D88}\u{3048}\u{308B}\u{30B3}\u{30D4}\u{30FC}\u{3092}\u{6570}\u{3048}\u{307E}\u{3059}\u{3002}", .zh: "\u{505C}\u{6B62}\u{80FD}\u{771F}\u{6B63}\u{505C}\u{6B62}\u{78C1}\u{76D8}\u{626B}\u{63CF}\u{FF1B}\u{91CD}\u{590D}\u{6587}\u{4EF6}\u{7684}\u{201C}\u{53EF}\u{91CA}\u{653E}\u{201D}\u{6570}\u{5B57}\u{6309}\u{5B9E}\u{9645}\u{4F1A}\u{5220}\u{9664}\u{7684}\u{526F}\u{672C}\u{8BA1}\u{7B97}\u{3002}", .pt: "Parar interrompe mesmo o escaneamento do disco, e o espa\u{00E7}o liberado nas duplicatas conta as c\u{00F3}pias que saem."])),
                ChangeItem(kind: .upd, text: L("Warnings are legible in the light theme, the icon and colour swatches can be reached from the keyboard, and sizes and names follow macOS in every language \u{2014} Russian abbreviates the byte the way the Finder does, French writes a lowercase ko, and each screen calls a permission by the name Settings gives it.", [.ru: "\u{041F}\u{0440}\u{0435}\u{0434}\u{0443}\u{043F}\u{0440}\u{0435}\u{0436}\u{0434}\u{0435}\u{043D}\u{0438}\u{044F} \u{0447}\u{0438}\u{0442}\u{0430}\u{044E}\u{0442}\u{0441}\u{044F} \u{0432} \u{0441}\u{0432}\u{0435}\u{0442}\u{043B}\u{043E}\u{0439} \u{0442}\u{0435}\u{043C}\u{0435}, \u{043E}\u{0431}\u{0440}\u{0430}\u{0437}\u{0446}\u{044B} \u{0438}\u{043A}\u{043E}\u{043D}\u{043E}\u{043A} \u{0438} \u{0446}\u{0432}\u{0435}\u{0442}\u{043E}\u{0432} \u{0434}\u{043E}\u{0441}\u{0442}\u{0438}\u{0436}\u{0438}\u{043C}\u{044B} \u{0441} \u{043A}\u{043B}\u{0430}\u{0432}\u{0438}\u{0430}\u{0442}\u{0443}\u{0440}\u{044B}, \u{0430} \u{0440}\u{0430}\u{0437}\u{043C}\u{0435}\u{0440}\u{044B} \u{0438} \u{043D}\u{0430}\u{0437}\u{0432}\u{0430}\u{043D}\u{0438}\u{044F} \u{0441}\u{043E}\u{0432}\u{043F}\u{0430}\u{0434}\u{0430}\u{044E}\u{0442} \u{0441} macOS: \u{0431}\u{0430}\u{0439}\u{0442} \u{0441}\u{043E}\u{043A}\u{0440}\u{0430}\u{0449}\u{0451}\u{043D} \u{0434}\u{043E} \u{00AB}\u{0411}\u{00BB}, \u{043A}\u{0430}\u{0436}\u{0434}\u{044B}\u{0439} \u{044D}\u{043A}\u{0440}\u{0430}\u{043D} \u{0437}\u{043E}\u{0432}\u{0451}\u{0442} \u{0440}\u{0430}\u{0437}\u{0440}\u{0435}\u{0448}\u{0435}\u{043D}\u{0438}\u{0435} \u{0442}\u{0430}\u{043A} \u{0436}\u{0435}, \u{043A}\u{0430}\u{043A} \u{041D}\u{0430}\u{0441}\u{0442}\u{0440}\u{043E}\u{0439}\u{043A}\u{0438}.", .es: "Los avisos se leen en el tema claro, las muestras de icono y color se alcanzan con el teclado, y los tama\u{00F1}os y nombres siguen a macOS en cada idioma.", .fr: "Les avertissements sont lisibles en th\u{00E8}me clair, les \u{00E9}chantillons d\u{2019}ic\u{00F4}ne et de couleur sont accessibles au clavier, et les tailles et les noms suivent macOS dans chaque langue.", .de: "Warnungen sind im hellen Erscheinungsbild lesbar, Symbol- und Farbfelder sind per Tastatur erreichbar, und Gr\u{00F6}\u{00DF}en und Namen folgen macOS in jeder Sprache.", .ja: "\u{30E9}\u{30A4}\u{30C8}\u{30C6}\u{30FC}\u{30DE}\u{3067}\u{8B66}\u{544A}\u{304C}\u{8AAD}\u{3081}\u{308B}\u{3088}\u{3046}\u{306B}\u{306A}\u{308A}\u{3001}\u{30A2}\u{30A4}\u{30B3}\u{30F3}\u{3068}\u{8272}\u{306E}\u{898B}\u{672C}\u{306B}\u{30AD}\u{30FC}\u{30DC}\u{30FC}\u{30C9}\u{3067}\u{5230}\u{9054}\u{3067}\u{304D}\u{3001}\u{5358}\u{4F4D}\u{3084}\u{540D}\u{79F0}\u{306F}\u{5404}\u{8A00}\u{8A9E}\u{3067} macOS \u{306B}\u{5408}\u{308F}\u{305B}\u{307E}\u{3057}\u{305F}\u{3002}", .zh: "\u{6D45}\u{8272}\u{4E3B}\u{9898}\u{4E0B}\u{7684}\u{8B66}\u{544A}\u{6E05}\u{6670}\u{53EF}\u{8BFB}\u{FF0C}\u{56FE}\u{6807}\u{4E0E}\u{989C}\u{8272}\u{8272}\u{5757}\u{53EF}\u{7528}\u{952E}\u{76D8}\u{62B5}\u{8FBE}\u{FF0C}\u{5C3A}\u{5BF8}\u{548C}\u{540D}\u{79F0}\u{5728}\u{6BCF}\u{79CD}\u{8BED}\u{8A00}\u{4E0B}\u{90FD}\u{4E0E} macOS \u{4E00}\u{81F4}\u{3002}", .pt: "Os avisos s\u{00E3}o leg\u{00ED}veis no tema claro, as amostras de \u{00ED}cone e cor s\u{00E3}o alcan\u{00E7}\u{00E1}veis pelo teclado, e tamanhos e nomes seguem o macOS em cada idioma."])),
                ChangeItem(kind: .fix, text: L("Escape closes the menu-bar panel, the way it closes every other menu on the Mac. It could be opened with a keyboard shortcut and then only be closed with the mouse.", [.ru: "Escape закрывает панель в строке меню — как закрывается любое меню на Mac. Открыть её можно было с клавиатуры, а закрыть только мышью.", .es: "Escape cierra el panel de la barra de menús, como cierra cualquier otro menú del Mac. Se podía abrir con el teclado y solo cerrar con el ratón.", .fr: "Échap ferme le panneau de la barre des menus, comme il ferme tous les autres menus du Mac. On pouvait l’ouvrir au clavier et seulement le fermer à la souris.", .de: "Escape schließt das Menüleisten-Panel, so wie es jedes andere Menü am Mac schließt. Es ließ sich per Tastatur öffnen und nur mit der Maus schließen.", .ja: "Esc キーでメニューバーパネルを閉じられます。キーボードで開けるのに、閉じるにはマウスが必要でした。", .zh: "按 Esc 键即可关闭菜单栏面板，就像关闭 Mac 上的其他菜单一样。此前可以用快捷键打开，却只能用鼠标关闭。", .pt: "Esc fecha o painel da barra de menus, como fecha qualquer outro menu no Mac. Dava para abrir pelo teclado e só fechar com o mouse."])),
                ChangeItem(kind: .upd, text: L("Helm’s language now reaches the parts macOS draws for it. The folder picker, its sidebar and the menus on a text field were English whatever language you had chosen. Numbers and dates follow the language too: a count of files is grouped the way your language groups digits, and a date is written the way your language writes one.", [.ru: "Язык Helm теперь распространяется и на то, что рисует macOS. Окно выбора папки, его боковое меню и меню у текстового поля оставались английскими при любом выбранном языке. Числа и даты тоже следуют языку: количество файлов разделяется по разрядам, а дата пишется так, как её пишут в вашем языке.", .es: "El idioma de Helm llega ahora a lo que dibuja macOS: el selector de carpetas, su barra lateral y los menús de un campo de texto seguían en inglés. Los números y las fechas también siguen al idioma.", .fr: "La langue de Helm atteint désormais ce que macOS dessine pour lui : le sélecteur de dossier, sa barre latérale et les menus d’un champ de texte restaient en anglais. Les nombres et les dates suivent aussi la langue.", .de: "Helms Sprache erreicht jetzt auch das, was macOS für es zeichnet: Der Ordnerauswahl-Dialog, seine Seitenleiste und die Menüs an einem Textfeld blieben englisch. Zahlen und Daten folgen ebenfalls der Sprache.", .ja: "macOS が描く部分にも Helm の言語が届くようになりました。フォルダ選択画面やそのサイドバー、テキストフィールドのメニューは英語のままでした。数字や日付も言語に合わせて表記されます。", .zh: "Helm 的语言现在也适用于 macOS 为它绘制的部分：选择文件夹的窗口、它的边栏以及文本框的菜单此前始终是英文。数字和日期也会按你的语言书写。", .pt: "O idioma do Helm agora alcança o que o macOS desenha para ele: o seletor de pastas, sua barra lateral e os menus de um campo de texto continuavam em inglês. Números e datas também seguem o idioma."])),
            ]),
            ChangelogEntry(version: "0.7.1", date: "2026-07-26", items: [
                ChangeItem(kind: .new, text: L("One key does both fixes. Pick right ⌘, ⌥, ⌃ or ⇧ and press it on its own: the first tap fixes the last word, the next puts it back. It keeps working as a modifier — held down, or pressed with anything else, it is an ordinary key again, so nothing you already use it for stops working.", [.ru: "Одна клавиша на оба действия. Выберите правую ⌘, ⌥, ⌃ или ⇧ и нажмите её отдельно: первое нажатие исправляет последнее слово, второе возвращает как было. Модификатором она быть не перестаёт — зажатая или нажатая вместе с чем-то ещё, это обычная клавиша, и всё, для чего вы её уже используете, продолжает работать.", .es: "Una tecla para ambas correcciones: elige ⌘, ⌥, ⌃ o ⇧ derecha y púlsala sola. La primera vez corrige la última palabra, la siguiente la devuelve. Sigue siendo un modificador cuando la mantienes o la combinas.", .fr: "Une touche pour les deux corrections : choisissez ⌘, ⌥, ⌃ ou ⇧ droite et appuyez seule. La première fois corrige le dernier mot, la suivante le restaure. Maintenue ou combinée, elle reste un modificateur.", .de: "Eine Taste für beide Korrekturen: rechte ⌘, ⌥, ⌃ oder ⇧ wählen und allein drücken. Das erste Mal korrigiert das letzte Wort, das nächste stellt es zurück. Gehalten oder kombiniert bleibt sie ein gewöhnlicher Modifikator.", .ja: "ひとつのキーで両方。右の ⌘ / ⌥ / ⌃ / ⇧ を選んで単独で押すと、1 回目で直前の単語を修正し、もう一度で元に戻します。押しっぱなしや同時押しでは通常の修飾キーのままです。", .zh: "一个键完成两件事：选择右侧 ⌘、⌥、⌃ 或 ⇧ 并单独按下，第一次修正上一个词，再按一次还原。按住或与其他键同时按下时，它仍是普通修饰键。", .pt: "Uma tecla para as duas correções: escolha ⌘, ⌥, ⌃ ou ⇧ da direita e pressione sozinha. A primeira vez corrige a última palavra, a seguinte desfaz. Segurada ou combinada, continua um modificador comum."])),
                ChangeItem(kind: .fix, text: L("In the light theme the icon shape and size previews were drawn white on a white card — a control the colour of its own background. They are drawn in the appearance they are shown in now, and so are the keyboard badge previews beside them.", [.ru: "В светлой теме превью формы и размера иконки рисовались белым по белой карточке — элемент управления цвета собственного фона. Теперь они рисуются в той теме, в которой показаны, — и превью значков «Клавиатуры» рядом тоже.", .es: "En el tema claro, las vistas previas de forma y tamaño del icono se dibujaban en blanco sobre una tarjeta blanca. Ahora se dibujan en la apariencia en la que se muestran.", .fr: "En thème clair, les aperçus de forme et de taille d’icône étaient dessinés en blanc sur une carte blanche. Ils sont désormais dessinés dans l’apparence où ils s’affichent.", .de: "Im hellen Erscheinungsbild wurden die Vorschauen für Symbolform und -größe weiß auf einer weißen Karte gezeichnet. Jetzt werden sie in dem Erscheinungsbild gezeichnet, in dem sie zu sehen sind.", .ja: "ライトテーマで、アイコンの形とサイズのプレビューが白いカードの上に白で描かれていました。表示されているテーマに合わせて描くようになりました。", .zh: "浅色主题下，图标形状与大小的预览在白色卡片上以白色绘制。现在它们按所处的外观绘制。", .pt: "No tema claro, as prévias de forma e tamanho do ícone eram desenhadas em branco sobre um cartão branco. Agora são desenhadas na aparência em que aparecem."])),
                ChangeItem(kind: .new, text: L("Disk takes a second look: a duplicate finder. Point it at the folder the ring is showing and it lists files that exist more than once — content compared, not names. One copy in each group is marked as the one that stays; the extras go to the basket, and deletion runs through the same guarded path as everything else. Hard links are one file and are never offered.", [.ru: "«Диск» смотрит второй раз: поиск дубликатов. Направьте его на папку, которую показывает кольцо, — он перечислит файлы, существующие больше одного раза. Сравнивается содержимое, а не имена. Одна копия в каждой группе помечена как остающаяся; лишние уходят в корзину, а удаление идёт тем же защищённым путём, что и всё остальное. Жёсткие ссылки — один файл, они не предлагаются.", .es: "Disco mira dos veces: un buscador de duplicados. Apúntalo a la carpeta del anillo y lista los archivos que existen más de una vez — se compara el contenido, no los nombres. Una copia de cada grupo queda marcada como la que se queda; las demás van a la cesta.", .fr: "Disque regarde une seconde fois : un chercheur de doublons. Pointez-le sur le dossier de l’anneau et il liste les fichiers présents plus d’une fois — contenu comparé, pas les noms. Une copie par groupe reste ; les autres vont au panier.", .de: "Festplatte schaut ein zweites Mal hin: eine Duplikatsuche. Auf den Ordner des Rings gerichtet listet sie Dateien, die mehr als einmal existieren — verglichen wird der Inhalt, nicht der Name. Eine Kopie je Gruppe bleibt; die übrigen wandern in den Korb.", .ja: "「ディスク」がもう一度チェック：重複ファイル検索。リングが示すフォルダを対象に、複数存在するファイルを一覧します。名前ではなく内容を比較。各グループの 1 つは残す印が付き、余分はバスケットへ。ハードリンクは同一ファイルなので提案されません。", .zh: "“磁盘”再看一眼：重复文件查找。指向环形图当前显示的文件夹，它会列出存在多份的文件——比较内容而非文件名。每组保留一份，多余的放入收集篮，删除仍走同样受保护的路径。硬链接是同一个文件，不会被列出。", .pt: "Disco dá uma segunda olhada: um buscador de duplicatas. Aponte-o para a pasta do anel e ele lista arquivos que existem mais de uma vez — conteúdo comparado, não nomes. Uma cópia de cada grupo fica; as demais vão para a cesta."])),
                ChangeItem(kind: .fix, text: L("Helm could crash outright when an application quit while the VPN module happened to be looking at the list of running programs. It was reading that list from the wrong thread, where macOS does not merely give a stale answer — it takes the process down.", [.ru: "Helm мог аварийно завершиться, когда приложение закрывалось ровно в тот момент, когда модуль VPN смотрел на список запущенных. Список читался не из того потока, а macOS в этом случае не просто отдаёт устаревший ответ — она роняет процесс.", .es: "Helm podía cerrarse de golpe si una app se cerraba justo cuando el módulo VPN miraba la lista de programas en ejecución. Se leía desde el hilo equivocado, donde macOS no devuelve un dato viejo: tumba el proceso.", .fr: "Helm pouvait planter net quand une app se fermait au moment où le module VPN consultait la liste des programmes en cours. Cette liste était lue depuis le mauvais thread, où macOS ne renvoie pas une valeur périmée — il tue le processus.", .de: "Helm konnte abstürzen, wenn ein Programm genau dann endete, während das VPN-Modul die Liste der laufenden Programme las. Sie wurde vom falschen Thread gelesen, wo macOS keine veraltete Antwort gibt — es beendet den Prozess.", .ja: "VPN モジュールが実行中プログラムの一覧を見ている最中にアプリが終了すると、Helm が異常終了することがありました。誤ったスレッドから一覧を読んでいたためで、この場合 macOS は古い値を返すのではなくプロセスを落とします。", .zh: "当某个程序恰好在 VPN 模块查看运行中程序列表时退出，Helm 可能直接崩溃。该列表是在错误的线程上读取的——这种情况下 macOS 不会返回过期数据，而是终止进程。", .pt: "O Helm podia travar de vez quando um app era encerrado no exato momento em que o módulo de VPN olhava a lista de programas em execução. A lista era lida na thread errada, onde o macOS não devolve um dado velho — ele derruba o processo."])),
                ChangeItem(kind: .upd, text: L("Two modules have shorter names: Disk Space is now Disk, and the layout switcher is now Keyboard. Earlier entries below still use the old names, which is what they were called at the time.", [.ru: "Два модуля стали называться короче: «Место на диске» — теперь «Диск», а переключатель раскладки — «Клавиатура». В записях ниже остались старые названия: так они назывались тогда.", .es: "Dos módulos tienen nombres más cortos: Espacio en disco ahora es Disco, y el cambiador de distribución es Teclado. Las entradas anteriores conservan los nombres de entonces.", .fr: "Deux modules portent un nom plus court : Espace disque devient Disque, et le changeur de disposition devient Clavier. Les entrées ci-dessous gardent les noms de l’époque.", .de: "Zwei Module heißen jetzt kürzer: Speicherplatz ist Festplatte, der Belegungswechsler ist Tastatur. Ältere Einträge unten behalten die damaligen Namen.", .ja: "2 つのモジュールの名前を短くしました。「ディスク容量」は「ディスク」に、配列切り替えは「キーボード」に。以下の古い項目は当時の名称のままです。", .zh: "两个模块改用更短的名称：“磁盘空间”现为“磁盘”，布局切换器现为“键盘”。下方旧条目仍用当时的名称。", .pt: "Dois módulos ganharam nomes mais curtos: Espaço em disco agora é Disco, e o trocador de layout é Teclado. As entradas antigas mantêm os nomes da época."])),
                ChangeItem(kind: .upd, text: L("The slower update channel is called Beta, not Stable. Helm has not reached 1.0, and nothing shipped so far has earned the word stable — the app says Beta on its About page for the same reason.", [.ru: "Медленный канал обновлений теперь называется «Бета», а не «Стабильный». Helm ещё не дошёл до 1.0, и ни одна сборка пока не заслужила слова «стабильный» — по той же причине на странице «О программе» появился шильдик «Бета».", .es: "El canal lento de actualizaciones se llama Beta, no Estable. Helm aún no llega a 1.0 — por eso también hay un distintivo Beta en Acerca de.", .fr: "Le canal de mise à jour lent s’appelle Bêta, plus Stable. Helm n’a pas atteint la 1.0 — d’où aussi le badge Bêta dans À propos.", .de: "Der langsamere Update-Kanal heißt Beta, nicht Stabil. Helm ist noch vor 1.0 — deshalb steht auch auf der Über-Seite Beta.", .ja: "更新チャンネルの「安定版」を「ベータ」に改名しました。Helm はまだ 1.0 前です。同じ理由で「情報」ページにもベータの表示が付きます。", .zh: "较慢的更新通道改名为“测试版”，不再叫“稳定版”。Helm 尚未到 1.0——“关于”页面也因此标注了测试版。", .pt: "O canal lento de atualizações passa a se chamar Beta, não Estável. O Helm ainda não chegou à 1.0 — por isso também há um selo Beta em Sobre."])),
                ChangeItem(kind: .new, text: L("Keyboard can show its own language indicator in the menu bar, with the choices the system’s one does not offer: letters plain, on a badge or in a frame, or a flag, at the size you pick, with a menu of your layouts. Off until you turn it on, since macOS shows its own.", [.ru: "«Клавиатура» умеет показывать свой индикатор языка в строке меню — с настройками, которых нет у системного: буквы, буквы с заливкой, буквы в контуре или флаг (эмодзи либо рисованный), нужного размера, и меню с вашими раскладками. По умолчанию выключен: системный никуда не девается.", .es: "Teclado puede mostrar su propio indicador de idioma en la barra de menús, con opciones que el del sistema no ofrece: letras, letras con relleno, con contorno o bandera (emoji o dibujada), del tamaño que elijas, y un menú con tus distribuciones. Desactivado por defecto.", .fr: "Clavier peut afficher son propre indicateur de langue dans la barre des menus, avec les choix que celui du système n’offre pas : lettres, pleines, encadrées, ou drapeau (emoji ou dessiné), à la taille voulue, et un menu de vos dispositions. Désactivé par défaut.", .de: "Tastatur kann eine eigene Sprachanzeige in der Menüleiste zeigen, mit den Optionen, die die des Systems nicht bietet: Buchstaben, gefüllt, umrandet oder eine Flagge (Emoji oder gezeichnet), in der gewünschten Größe, samt Menü deiner Belegungen. Standardmäßig aus.", .ja: "「キーボード」がメニューバーに独自の入力ソース表示を出せます。システム版では変えられない見た目を選べます：文字、塗り、枠線、旗（絵文字／描画）、サイズも自由で、配列のメニュー付き。既定はオフです。", .zh: "“键盘”可在菜单栏显示自己的语言指示器，提供系统版本没有的选项：字母、填充、描边，或旗帜（表情／绘制），尺寸可选，并带布局菜单。默认关闭。", .pt: "O Teclado pode mostrar seu próprio indicador de idioma na barra de menus, com opções que o do sistema não oferece: letras, preenchidas, com contorno, ou bandeira (emoji ou desenhada), no tamanho que quiser, e um menu com seus layouts. Desligado por padrão."])),
                ChangeItem(kind: .new, text: L("Every layout has a real flag now. Helm drew them itself for a while, but a table of bands and crosses cannot hold Mexico’s eagle, Portugal’s armillary sphere or Korea’s trigrams — half a dozen flags were approximations because of it. These come from flag-icons under the MIT licence (credited on this page): rectangular, accurate, and legible down to the smallest badge size. A layout that names no country still keeps its letters.", [.ru: "У каждой раскладки теперь настоящий флаг. Helm какое-то время рисовал их сам, но таблица полос и крестов не вмещает мексиканского орла, португальскую армиллярную сферу и корейские триграммы — с полдюжины флагов из-за этого были приближениями. Теперь это flag-icons под лицензией MIT (указано на этой же странице): прямоугольные, точные и читаемые вплоть до самого мелкого размера значка. Раскладка без страны по-прежнему остаётся буквами.", .es: "Cada distribución tiene ahora una bandera de verdad: flag-icons bajo licencia MIT (acreditado en esta página). Rectangulares, precisas y legibles hasta el tamaño más pequeño. Una distribución sin país conserva sus letras.", .fr: "Chaque disposition a désormais un vrai drapeau : flag-icons sous licence MIT (crédité sur cette page). Rectangulaires, exacts et lisibles jusqu’à la plus petite taille. Une disposition sans pays garde ses lettres.", .de: "Jede Belegung hat jetzt eine echte Flagge: flag-icons unter MIT-Lizenz (auf dieser Seite genannt). Rechteckig, korrekt und bis zur kleinsten Größe lesbar. Eine Belegung ohne Land behält ihre Buchstaben.", .ja: "すべての配列に本物の旗が付きました。MIT ライセンスの flag-icons です（このページに表示）。長方形で正確、最小サイズでも読み取れます。国が定まらない配列は文字のままです。", .zh: "每个布局现在都有真正的旗帜：MIT 许可的 flag-icons（本页已署名）。矩形、准确，最小尺寸下依然清晰。没有国家归属的布局仍保持字母显示。", .pt: "Cada layout agora tem uma bandeira de verdade: flag-icons sob licença MIT (creditado nesta página). Retangulares, precisas e legíveis até no menor tamanho. Um layout sem país mantém as letras."])),
                ChangeItem(kind: .upd, text: L("After an update Helm tells you which permissions stopped working and takes you straight to the right pane. An update always revokes them — the checkbox stays ticked while nothing works.", [.ru: "После обновления Helm говорит, какие разрешения перестали действовать, и ведёт прямо в нужную панель. Обновление всегда их сбрасывает: галочка остаётся стоять, а работать перестаёт.", .es: "Tras una actualización, Helm indica qué permisos dejaron de funcionar y te lleva al panel correcto. Una actualización siempre los revoca: la casilla sigue marcada y nada funciona.", .fr: "Après une mise à jour, Helm indique quelles autorisations ont cessé de fonctionner et vous mène au bon panneau. Une mise à jour les révoque toujours : la case reste cochée et plus rien ne marche.", .de: "Nach einem Update sagt Helm, welche Berechtigungen nicht mehr wirken, und führt direkt zum richtigen Bereich. Ein Update entzieht sie immer — das Häkchen bleibt, die Funktion nicht.", .ja: "アップデート後、どの権限が効かなくなったかを伝え、該当の設定画面へ直接案内します。アップデートは必ず権限を失わせます（チェックは付いたままなのに動きません）。", .zh: "更新后，Helm 会说明哪些权限已失效，并直接带你到对应面板。更新总会撤销权限——勾选还在，功能却没了。", .pt: "Depois de uma atualização, o Helm diz quais permissões pararam de funcionar e leva direto ao painel certo. Uma atualização sempre as revoga: a caixa continua marcada e nada funciona."])),
                ChangeItem(kind: .new, text: L("Keyboard: a word typed in the wrong keyboard layout is fixed as you type — ghbdtn becomes привет — and the input source follows. Only when the word is not a word as typed and is one once swapped, so anything valid is left alone.", [.ru: "«Клавиатура»: слово, набранное не в той раскладке, исправляется по ходу набора — ghbdtn становится привет, — и раскладка переключается следом. Только если как набрано это не слово, а после смены раскладки — слово; всё осмысленное остаётся как есть.", .es: "Teclado: una palabra escrita en la distribución equivocada se corrige mientras escribes y la fuente de entrada la sigue. Solo si no es palabra tal cual y sí lo es al convertirla.", .fr: "Clavier : un mot tapé dans la mauvaise disposition est corrigé pendant la saisie, et la source de saisie suit. Uniquement s’il n’est pas un mot tel quel et en devient un une fois converti.", .de: "Tastatur: Ein in der falschen Belegung getipptes Wort wird beim Tippen korrigiert, und die Eingabequelle folgt. Nur wenn es so getippt keines ist und nach dem Tausch eines wird.", .ja: "「キーボード」：誤った配列で入力した単語を入力中に修正し、入力ソースも切り替えます。入力どおりでは単語でなく、変換すると単語になる場合のみです。", .zh: "“键盘”：用错误布局输入的单词会在输入时被修正，输入法也随之切换。仅当按原样不是单词、转换后才是单词时才处理。", .pt: "Teclado: uma palavra digitada no layout errado é corrigida enquanto você digita, e a fonte de entrada acompanha. Só quando não é palavra como digitada e passa a ser após a troca."])),
                ChangeItem(kind: .new, text: L("It leaves terminals and password managers alone, stops while the system is in secure input, and never writes down what you type. Every change can be undone with a shortcut, and you can list words and apps it must not touch.", [.ru: "Он не трогает терминалы и менеджеры паролей, останавливается при защищённом вводе системы и никогда не записывает набранное. Любую замену можно вернуть горячей клавишей, а слова и приложения, которые трогать нельзя, задаются списком.", .es: "Deja en paz terminales y gestores de contraseñas, se detiene en entrada segura y nunca anota lo que escribes. Cada cambio se deshace con un atajo, y puedes listar palabras y apps intocables.", .fr: "Il ignore terminaux et gestionnaires de mots de passe, s’arrête en saisie sécurisée et n’écrit jamais ce que vous tapez. Chaque changement s’annule par un raccourci ; mots et apps intouchables se listent.", .de: "Terminals und Passwortmanager bleiben unangetastet, bei sicherer Eingabe hält es an, und Getipptes wird nie festgehalten. Jede Änderung lässt sich per Kurzbefehl zurücknehmen; Wörter und Apps kann man ausnehmen.", .ja: "ターミナルとパスワード管理アプリには触れず、セキュア入力中は停止し、入力内容を記録しません。変更はショートカットで元に戻せ、触れない単語やアプリを一覧で指定できます。", .zh: "它不碰终端和密码管理器，系统进入安全输入时暂停，且从不记录你输入的内容。每次修改都可用快捷键撤销，也可列出不得改动的词与应用。", .pt: "Deixa terminais e gerenciadores de senha em paz, para durante entrada segura e nunca anota o que você digita. Cada mudança se desfaz por atalho, e há listas de palavras e apps intocáveis."])),
                ChangeItem(kind: .fix, text: L("Connecting a VPN no longer makes the rest of Helm stutter — the work moved off the thread that draws the interface.", [.ru: "Подключение VPN больше не подтормаживает остальной Helm — работа ушла с потока, который рисует интерфейс.", .es: "Conectar una VPN ya no hace que el resto de Helm se entrecorte: el trabajo salió del hilo que dibuja la interfaz.", .fr: "Connecter un VPN ne fait plus saccader le reste de Helm : le travail a quitté le fil qui dessine l’interface.", .de: "Eine VPN-Verbindung lässt den Rest von Helm nicht mehr stocken — die Arbeit läuft nicht mehr auf dem Zeichen-Thread.", .ja: "VPN 接続中に Helm の他の部分がもたつかなくなりました。処理を描画スレッドから外しました。", .zh: "连接 VPN 时 Helm 其余部分不再卡顿——相关工作已移出绘制界面的线程。", .pt: "Conectar uma VPN não faz mais o resto do Helm engasgar — o trabalho saiu da thread que desenha a interface."])),
                ChangeItem(kind: .upd, text: L("VoiceOver reads Helm properly: every icon button has a name, and a collapsed section is no longer read out.", [.ru: "VoiceOver читает Helm как следует: у каждой иконочной кнопки есть имя, а свёрнутый блок больше не зачитывается.", .es: "VoiceOver lee Helm como debe: cada botón de icono tiene nombre y una sección plegada ya no se lee.", .fr: "VoiceOver lit Helm correctement : chaque bouton d’icône a un nom, et une section repliée n’est plus lue.", .de: "VoiceOver liest Helm richtig: Jeder Symbolknopf hat einen Namen, und ein zugeklappter Abschnitt wird nicht mehr vorgelesen.", .ja: "VoiceOver が Helm を正しく読み上げます。アイコンボタンに名前が付き、折りたたまれた項目は読まれません。", .zh: "VoiceOver 能正确朗读 Helm：每个图标按钮都有名称，折叠的区块不再被读出。", .pt: "O VoiceOver lê o Helm direito: todo botão de ícone tem nome, e uma seção recolhida não é mais lida."])),
                ChangeItem(kind: .fix, text: L("The icon shape, icon size and both colours can be chosen from the keyboard, and Escape leaves the shortcut recorder.", [.ru: "Форму и размер иконки и оба цвета теперь можно выбрать с клавиатуры, а из записи горячей клавиши выпускает Escape.", .es: "La forma y el tamaño del icono y ambos colores se eligen con el teclado, y Escape sale del grabador de atajos.", .fr: "La forme et la taille de l’icône et les deux couleurs se choisissent au clavier, et Échap quitte l’enregistrement du raccourci.", .de: "Symbolform, Symbolgröße und beide Farben lassen sich mit der Tastatur wählen, und Escape verlässt die Kurzbefehl-Aufnahme.", .ja: "アイコンの形・サイズと2つの色をキーボードで選べます。ショートカット記録は Esc で抜けられます。", .zh: "图标形状、大小和两种颜色都可用键盘选择，Esc 可退出快捷键录制。", .pt: "A forma e o tamanho do ícone e as duas cores podem ser escolhidos pelo teclado, e Esc sai do gravador de atalho."])),
                ChangeItem(kind: .upd, text: L("App Uninstaller opens straight away. It used to measure every app on your Mac before showing anything — four seconds, nine on a cold start. The list appears now and the sizes fill in behind it.", [.ru: "«Удаление приложений» открывается сразу. Раньше оно измеряло каждое приложение на Mac прежде чем показать хоть что-то — четыре секунды, девять на холодную. Теперь список появляется сразу, а размеры подставляются следом.", .es: "El Desinstalador abre de inmediato. Antes medía cada app antes de mostrar nada: cuatro segundos, nueve en frío. Ahora aparece la lista y los tamaños se rellenan después.", .fr: "La désinstallation s’ouvre tout de suite. Elle mesurait chaque app avant d’afficher quoi que ce soit — quatre secondes, neuf à froid. La liste apparaît, les tailles suivent.", .de: "Die Deinstallation öffnet sofort. Vorher wurde jede App vermessen, bevor überhaupt etwas erschien — vier Sekunden, neun bei kaltem Start. Jetzt kommt die Liste zuerst, die Größen danach.", .ja: "アンインストーラがすぐ開きます。以前は表示前にすべてのアプリを計測していました（4秒、コールドで9秒）。一覧を先に表示し、サイズは後から埋まります。", .zh: "卸载器立即打开。此前它会先测量每个应用才显示内容——四秒，冷启动九秒。现在先出列表，容量随后补上。", .pt: "O Desinstalador abre na hora. Antes media cada app antes de mostrar qualquer coisa — quatro segundos, nove a frio. Agora a lista aparece e os tamanhos chegam depois."])),
                ChangeItem(kind: .upd, text: L("Disk and Login Items are quicker to open, and the app stops freezing for a moment while it reads or saves a scan.", [.ru: "«Диск» и «Объекты входа» открываются быстрее, а приложение больше не подвисает на мгновение, читая или сохраняя результат сканирования.", .es: "Disco y Ítems de inicio abren más rápido, y la app ya no se congela un instante al leer o guardar un escaneo.", .fr: "Disque et Ouverture s’ouvrent plus vite, et l’app ne se fige plus un instant en lisant ou enregistrant une analyse.", .de: "Festplatte und Anmeldeobjekte öffnen schneller, und die App friert nicht mehr kurz ein, während sie einen Scan liest oder sichert.", .ja: "「ディスク」と「ログイン項目」の表示が速くなり、スキャン結果の読み書き中に一瞬固まることがなくなりました。", .zh: "“磁盘”和“登录项”打开更快，读写扫描结果时不再短暂卡顿。", .pt: "Disco e Itens de início abrem mais rápido, e o app não congela por um instante ao ler ou salvar um escaneamento."])),
                ChangeItem(kind: .fix, text: L("On a wide window the settings no longer drift: every page starts at the same left edge, and switching between them stops shifting the content sideways.", [.ru: "На широком окне настройки больше не разъезжаются: все страницы начинаются от одного левого края, и переключение между ними не сдвигает содержимое вбок.", .es: "En una ventana ancha los ajustes ya no se desalinean: todas las páginas empiezan en el mismo borde izquierdo.", .fr: "Sur une fenêtre large, les réglages ne dérivent plus : toutes les pages commencent au même bord gauche.", .de: "In einem breiten Fenster verrutschen die Einstellungen nicht mehr: Alle Seiten beginnen an derselben linken Kante.", .ja: "ウィンドウを広げても設定がずれません。すべてのページが同じ左端から始まります。", .zh: "窗口拉宽时设置不再错位：所有页面从同一左边缘开始。", .pt: "Em uma janela larga os ajustes não desalinham mais: todas as páginas começam na mesma borda esquerda."])),
                ChangeItem(kind: .fix, text: L("The small labels above each module’s figures are legible again, in both light and dark.", [.ru: "Мелкие подписи над показателями модулей снова читаются — и в светлой теме, и в тёмной.", .es: "Las etiquetas pequeñas sobre las cifras de cada módulo vuelven a leerse, en claro y en oscuro.", .fr: "Les petites étiquettes au-dessus des chiffres de chaque module sont de nouveau lisibles, en clair comme en sombre.", .de: "Die kleinen Beschriftungen über den Kennzahlen jedes Moduls sind wieder lesbar — hell wie dunkel.", .ja: "各モジュールの数値の上にある小さなラベルが、ライトでもダークでも読めるようになりました。", .zh: "各模块数字上方的小标签重新变得清晰，浅色与深色模式皆是。", .pt: "As legendas pequenas acima dos números de cada módulo voltaram a ser legíveis, no claro e no escuro."])),
                ChangeItem(kind: .fix, text: L("Disk no longer lets a top-level folder of the disk — Users, Applications, Library — go into the basket. What is inside them still can.", [.ru: "«Диск» больше не даёт положить в корзину папку верхнего уровня — «Пользователи», «Программы», «Библиотеки». Их содержимое — по-прежнему можно.", .es: "Disco ya no permite poner en la cesta una carpeta de nivel superior del disco. Su contenido sí.", .fr: "Disque ne laisse plus mettre au panier un dossier de premier niveau du disque. Leur contenu, si.", .de: "Festplatte lässt keinen Ordner der obersten Ebene mehr in den Korb legen. Ihr Inhalt schon.", .ja: "「ディスク」で、ディスク直下のフォルダをバスケットに入れられないようにしました。中身は従来どおり入れられます。", .zh: "“磁盘”不再允许把磁盘顶层文件夹放入收集篮，其中的内容仍然可以。", .pt: "Disco não deixa mais colocar na cesta uma pasta de nível superior do disco. O conteúdo delas, sim."])),
                ChangeItem(kind: .fix, text: L("An app can no longer claim other apps' files as its own leftovers by naming itself unusually.", [.ru: "Программа больше не может выдать чужие файлы за свои остатки, назвавшись необычным образом.", .es: "Una app ya no puede reclamar los archivos de otras como restos propios usando un nombre inusual.", .fr: "Une app ne peut plus revendiquer les fichiers des autres comme ses résidus en se donnant un nom inhabituel.", .de: "Eine App kann fremde Dateien nicht mehr als eigene Reste ausgeben, indem sie sich ungewöhnlich benennt.", .ja: "アプリが異常な名前を名乗って他のアプリのファイルを自分の残存物として提示することはできなくなりました。", .zh: "应用不能再通过使用异常名称，把其他应用的文件说成自己的残留。", .pt: "Um app não pode mais reivindicar arquivos de outros como restos próprios usando um nome incomum."])),
                ChangeItem(kind: .fix, text: L("Turning a login item off no longer clears everything else you had ticked.", [.ru: "Отключение одного элемента автозапуска больше не снимает все остальные отметки.", .es: "Desactivar un ítem de inicio ya no borra el resto de tu selección.", .fr: "Désactiver un élément d’ouverture n’efface plus le reste de votre sélection.", .de: "Ein Startobjekt auszuschalten löscht nicht mehr deine übrige Auswahl.", .ja: "ログイン項目をオフにしても、他のチェックが消えなくなりました。", .zh: "关闭某个登录项时，不再清空你已勾选的其他项。", .pt: "Desativar um item de início não apaga mais o resto da sua seleção."])),
                ChangeItem(kind: .fix, text: L("Disk keeps working after the module is switched off and on again, and Keep Awake stops asking for your password every session.", [.ru: "«Диск» продолжает работать после выключения и повторного включения модуля, а «Не спать» перестал спрашивать пароль каждый сеанс.", .es: "Disco sigue funcionando tras apagar y encender el módulo, y Mantener activo deja de pedir la contraseña cada sesión.", .fr: "Disque continue de fonctionner après avoir éteint puis rallumé le module, et Rester éveillé cesse de demander le mot de passe à chaque session.", .de: "Festplatte funktioniert weiter, nachdem das Modul aus- und wieder eingeschaltet wurde, und Wach halten fragt nicht mehr in jeder Sitzung nach dem Passwort.", .ja: "モジュールをオフ→オンしても「ディスク」が動き続け、「スリープ防止」が毎回パスワードを求めなくなりました。", .zh: "关闭再开启模块后“磁盘”仍可用，“保持唤醒”也不再每次都要求输入密码。", .pt: "Disco continua funcionando depois de desligar e religar o módulo, e o Manter ativo deixa de pedir a senha toda sessão."])),
                ChangeItem(kind: .upd, text: L("Permissions are called what System Settings calls them, so the row Helm points you at is the row you find.", [.ru: "Разрешения называются так же, как в «Системных настройках», — вы находите именно тот пункт, на который Helm ссылается.", .es: "Los permisos se llaman como en Ajustes del Sistema, así que encuentras exactamente la fila que Helm indica.", .fr: "Les autorisations portent le nom qu’elles ont dans Réglages Système : vous trouvez exactement la ligne indiquée.", .de: "Berechtigungen heißen wie in den Systemeinstellungen — du findest genau die Zeile, auf die Helm zeigt.", .ja: "アクセス権の名称をシステム設定に合わせました。案内された項目がそのまま見つかります。", .zh: "权限名称与系统设置一致，Helm 指向的那一行就能找到。", .pt: "As permissões têm o nome que aparece nos Ajustes do Sistema, então você encontra exatamente a linha indicada."])),
                ChangeItem(kind: .upd, text: L("VoiceOver can find Helm in the menu bar, and \"Reduce motion\" is respected throughout.", [.ru: "VoiceOver находит Helm в строке меню, а «Уменьшение движения» соблюдается везде.", .es: "VoiceOver encuentra Helm en la barra de menús y se respeta «Reducir movimiento».", .fr: "VoiceOver trouve Helm dans la barre des menus, et « Réduire les animations » est respecté partout.", .de: "VoiceOver findet Helm in der Menüleiste, und „Bewegung reduzieren“ wird überall beachtet.", .ja: "VoiceOver がメニューバーの Helm を認識し、「視差効果を減らす」を全体で尊重します。", .zh: "VoiceOver 能在菜单栏中找到 Helm，且全程遵循“减弱动态效果”。", .pt: "O VoiceOver encontra o Helm na barra de menus, e “Reduzir movimento” é respeitado em todo o app."])),
                ChangeItem(kind: .fix, text: L("The log Helm keeps for troubleshooting no longer writes down the names of your VPN connections, your apps, or the path to your home folder.", [.ru: "Журнал, который Helm ведёт для диагностики, больше не записывает названия ваших VPN-подключений, имена приложений и путь к домашней папке.", .es: "El registro de diagnóstico ya no anota los nombres de tus conexiones VPN, tus apps ni la ruta a tu carpeta personal.", .fr: "Le journal de diagnostic n’inscrit plus les noms de vos connexions VPN, de vos apps ni le chemin de votre dossier personnel.", .de: "Das Diagnoseprotokoll notiert keine Namen deiner VPN-Verbindungen, Apps oder den Pfad zu deinem Benutzerordner mehr.", .ja: "診断用ログに、VPN 接続名・アプリ名・ホームフォルダのパスを記録しなくなりました。", .zh: "用于排查问题的日志不再记录你的 VPN 连接名称、应用名称和个人文件夹路径。", .pt: "O registro de diagnóstico não anota mais os nomes das suas conexões VPN, dos seus apps nem o caminho da sua pasta pessoal."])),
                ChangeItem(kind: .upd, text: L("Leftovers found by an app’s name rather than its identifier are marked as guesses and are no longer ticked in advance — names collide, and a guess should cost a click to accept.", [.ru: "Остатки, найденные по имени приложения, а не по её идентификатору, помечены как догадки и больше не отмечены заранее: имена совпадают у разных приложений, и согласиться с догадкой должно стоить клика.", .es: "Los restos hallados por el nombre de la app y no por su identificador se marcan como conjeturas y ya no vienen marcados: los nombres coinciden entre apps.", .fr: "Les résidus trouvés par le nom de l’app plutôt que par son identifiant sont signalés comme des suppositions et ne sont plus cochés d’avance : les noms se ressemblent.", .de: "Reste, die über den App-Namen statt die Kennung gefunden wurden, sind als Vermutung markiert und nicht mehr vorausgewählt — Namen wiederholen sich.", .ja: "識別子ではなくアプリ名で見つかった残存物は「推測」と表示し、既定では選択しません。名前は他のアプリと重なります。", .zh: "凭应用名称（而非标识符）找到的残留会标为推测，且不再预先勾选——不同应用可能同名。", .pt: "Restos encontrados pelo nome do app, e não pelo identificador, são marcados como suposição e não vêm mais marcados — nomes se repetem."])),
                ChangeItem(kind: .fix, text: L("Turning off \"stay awake with the lid closed\" now also removes the passwordless permission it had to install. It used to stay on your Mac for good.", [.ru: "Выключение «не спать с закрытой крышкой» теперь снимает и беспарольное разрешение, которое для этого пришлось установить. Раньше оно оставалось на Mac навсегда.", .es: "Desactivar «seguir activo con la tapa cerrada» ahora también elimina el permiso sin contraseña que hubo que instalar. Antes se quedaba para siempre.", .fr: "Désactiver « rester éveillé capot fermé » retire aussi l’autorisation sans mot de passe qu’il avait fallu installer. Elle restait auparavant à demeure.", .de: "Wird „bei geschlossenem Deckel wach bleiben“ ausgeschaltet, entfernt Helm jetzt auch die dafür nötige passwortlose Berechtigung. Bisher blieb sie dauerhaft.", .ja: "「フタを閉じてもスリープしない」をオフにすると、そのために追加したパスワード不要の許可も削除します。従来は残り続けていました。", .zh: "关闭“合盖仍保持唤醒”时，会一并移除为此安装的免密码权限。此前它会永久留在你的 Mac 上。", .pt: "Desativar “continuar acordado com a tampa fechada” agora remove também a permissão sem senha que precisou ser instalada. Antes ela ficava para sempre."])),
                ChangeItem(kind: .fix, text: L("Quitting an app now disconnects only a VPN Helm itself raised for it — never one you dialled up by hand.", [.ru: "Закрытие приложения теперь отключает только тот VPN, который Helm сам для неё поднял, — и никогда тот, что вы включили вручную.", .es: "Cerrar una app ahora desconecta solo la VPN que Helm levantó para ella, nunca una que estableciste a mano.", .fr: "Quitter une app ne déconnecte que le VPN que Helm avait établi pour elle, jamais celui que vous aviez lancé vous-même.", .de: "Das Beenden einer App trennt nur das VPN, das Helm dafür aufgebaut hat — nie eines, das du selbst gestartet hast.", .ja: "アプリを終了したとき、切断するのは Helm がそのアプリのために接続した VPN だけになりました。手動で接続したものは切りません。", .zh: "退出应用时，只会断开 Helm 为它建立的 VPN，绝不会断开你手动连接的。", .pt: "Encerrar um app agora desconecta apenas a VPN que o Helm levantou para ele — nunca uma que você conectou à mão."])),
                ChangeItem(kind: .fix, text: L("Homebrew search tells apps and command-line tools apart again, so installing an app installs the app.", [.ru: "Поиск в Homebrew снова отличает приложения от консольных утилит, поэтому установка приложения ставит именно приложение.", .es: "La búsqueda de Homebrew vuelve a distinguir apps de herramientas de línea de comandos, así que instalar una app instala la app.", .fr: "La recherche Homebrew distingue à nouveau les apps des outils en ligne de commande : installer une app installe bien l’app.", .de: "Die Homebrew-Suche unterscheidet wieder Apps von Kommandozeilen-Werkzeugen — eine App zu installieren installiert die App.", .ja: "Homebrew 検索がアプリとコマンドラインツールを再び区別します。アプリを選べばアプリが入ります。", .zh: "Homebrew 搜索重新区分应用与命令行工具，安装应用时装的就是应用。", .pt: "A busca do Homebrew volta a distinguir apps de ferramentas de linha de comando: instalar um app instala o app."])),
                ChangeItem(kind: .fix, text: L("App Uninstaller no longer offers the files of installed apps as leftovers. Apps kept one folder down — Adobe Acrobat DC, Microsoft Office — were invisible to it, and nothing is pre-selected any more.", [.ru: "«Удаление приложений» больше не предлагает как остатки файлы установленных приложений. Приложения, лежащие во вложенной папке — Adobe Acrobat DC, Microsoft Office, — были ему не видны; и ничего больше не отмечено заранее.", .es: "El Desinstalador ya no ofrece como restos los archivos de apps instaladas. Las apps dentro de subcarpetas eran invisibles, y ya nada viene preseleccionado.", .fr: "La désinstallation ne propose plus comme résidus les fichiers d’apps installées. Les apps rangées dans un sous-dossier lui échappaient ; et plus rien n’est présélectionné.", .de: "Die Deinstallation bietet keine Dateien installierter Apps mehr als Reste an. Apps in Unterordnern waren unsichtbar; außerdem ist nichts mehr vorausgewählt.", .ja: "アンインストーラが、インストール済みアプリのファイルを残存物として提示しなくなりました。サブフォルダ内のアプリが認識されていませんでした。既定の選択もなくなりました。", .zh: "卸载器不再把已安装应用的文件当作残留。位于子文件夹中的应用此前不可见；且不再预先勾选任何项。", .pt: "O Desinstalador não oferece mais arquivos de apps instalados como restos. Apps em subpastas eram invisíveis; e nada vem pré-selecionado."])),
                ChangeItem(kind: .upd, text: L("Each login item now offers what is actually possible: turn it off, show it in Finder, or delete it — with a word about why, when a password would be needed.", [.ru: "У каждого элемента автозапуска теперь ровно те действия, которые возможны: отключить, показать в Finder или удалить — и объяснение, если нужен пароль администратора.", .es: "Cada elemento de inicio ofrece lo que realmente es posible: desactivar, mostrar en Finder o eliminar — y explica cuándo haría falta contraseña.", .fr: "Chaque élément d’ouverture propose ce qui est réellement possible : désactiver, afficher dans le Finder ou supprimer — en expliquant quand un mot de passe serait requis.", .de: "Jedes Startobjekt bietet, was wirklich geht: ausschalten, im Finder zeigen oder löschen — mit Hinweis, wenn ein Passwort nötig wäre.", .ja: "各ログイン項目に、実際に可能な操作だけを表示：オフにする、Finderに表示、削除。パスワードが必要な場合はその理由も示します。", .zh: "每个登录项只提供实际可行的操作：关闭、在访达中显示或删除——需要密码时会说明原因。", .pt: "Cada item de início oferece o que é realmente possível: desativar, mostrar no Finder ou excluir — e explica quando exigiria senha."])),
                ChangeItem(kind: .fix, text: L("When a file cannot be moved, Helm now says which one and why instead of reporting success. Deleting a Homebrew package asks first, and the disk basket lists what is in it before it goes to the Trash.", [.ru: "Если файл переместить не удалось, Helm называет какой и почему, а не рапортует об успехе. Удаление пакета Homebrew теперь спрашивает подтверждение, а корзина «Места на диске» показывает, что в ней лежит.", .es: "Si un archivo no se puede mover, Helm dice cuál y por qué en vez de informar éxito. Desinstalar un paquete de Homebrew ahora pregunta, y la cesta del disco lista su contenido.", .fr: "Quand un fichier ne peut être déplacé, Helm dit lequel et pourquoi au lieu d’annoncer une réussite. Désinstaller un paquet Homebrew demande confirmation, et le panier du disque affiche son contenu.", .de: "Lässt sich eine Datei nicht verschieben, nennt Helm welche und warum, statt Erfolg zu melden. Das Entfernen eines Homebrew-Pakets fragt nach, und der Korb listet seinen Inhalt.", .ja: "移動できないファイルがあれば、成功と報告せずに「どれが・なぜ」を表示します。Homebrew パッケージの削除は確認を求め、ディスクのバスケットは中身を一覧します。", .zh: "文件无法移动时，Helm 会说明是哪一个、为什么，而不是报告成功。卸载 Homebrew 包会先确认，磁盘收集篮会列出其内容。", .pt: "Quando um arquivo não pode ser movido, o Helm diz qual e por quê em vez de relatar sucesso. Remover um pacote do Homebrew pede confirmação, e a cesta do disco lista o conteúdo."])),
                ChangeItem(kind: .new, text: L("Login items can be switched off instead of only deleted. Helm uses the same list macOS itself uses, so the choice survives a reboot, needs no password, and can be undone here or in System Settings.", [.ru: "Элементы автозапуска теперь можно отключить, а не только удалить. Helm пользуется тем же списком, что и сама macOS: выбор переживает перезагрузку, пароль не нужен, вернуть можно здесь или в системных настройках.", .es: "Los elementos de inicio ahora se pueden desactivar, no solo eliminar. Helm usa la misma lista que macOS: sobrevive al reinicio, no pide contraseña y se puede deshacer.", .fr: "Les éléments d’ouverture peuvent être désactivés, pas seulement supprimés. Helm utilise la liste de macOS : le choix survit au redémarrage, sans mot de passe, et se défait.", .de: "Anmeldeobjekte lassen sich ausschalten statt nur löschen. Helm nutzt dieselbe Liste wie macOS: die Wahl übersteht einen Neustart, braucht kein Passwort und ist umkehrbar.", .ja: "ログイン項目は削除だけでなくオフにできます。macOS 自身と同じ一覧を使うため、再起動後も維持され、パスワード不要で元に戻せます。", .zh: "登录项现在可以关闭，而不只是删除。Helm 使用 macOS 自身的列表：重启后依然有效，无需密码，可随时恢复。", .pt: "Itens de início agora podem ser desativados, não só excluídos. O Helm usa a mesma lista do macOS: sobrevive a reinícios, não pede senha e é reversível."])),
                ChangeItem(kind: .upd, text: L("A filter hides the kinds you are not reviewing — system extensions, for instance.", [.ru: "Фильтр прячет виды, которые сейчас не смотрите, — например, системные расширения.", .es: "Un filtro oculta los tipos que no estás revisando, por ejemplo las extensiones del sistema.", .fr: "Un filtre masque les types que vous n’examinez pas, les extensions système par exemple.", .de: "Ein Filter blendet Arten aus, die du gerade nicht prüfst — etwa Systemerweiterungen.", .ja: "いま見ていない種類（システム機能拡張など）はフィルタで隠せます。", .zh: "筛选器可隐藏你当前不查看的类型，例如系统扩展。", .pt: "Um filtro oculta os tipos que você não está revisando — extensões do sistema, por exemplo."])),
                ChangeItem(kind: .fix, text: L("Keep Awake’s status figures update as things happen instead of freezing at whatever they were when the page opened.", [.ru: "Показатели состояния «Не спать» обновляются по ходу дела, а не застывают на том, что было при открытии страницы.", .es: "Las cifras de estado de Mantener activo se actualizan en tiempo real en lugar de congelarse al abrir la página.", .fr: "Les indicateurs de Rester éveillé se mettent à jour en direct au lieu de rester figés à l’ouverture.", .de: "Die Statuszahlen von Wach halten aktualisieren sich laufend, statt beim Öffnen einzufrieren.", .ja: "「スリープ防止」の状態表示は、ページを開いた時点で止まらずリアルタイムに更新されます。", .zh: "“保持唤醒”的状态数字会实时更新，不再停留在打开页面时的数值。", .pt: "Os indicadores do Manter ativo se atualizam ao vivo, em vez de congelar na abertura da página."])),
                ChangeItem(kind: .new, text: L("Login Items & Extensions now lists system extensions themselves — what they are, whose they are, and which ones outlived the app that installed them.", [.ru: "«Объекты входа и расширения» теперь показывает и сами системные расширения: что это, чьё это и какие из них пережили удалённое приложение.", .es: "Ítems de inicio y extensiones ahora lista las propias extensiones del sistema: qué son, de quién son y cuáles sobrevivieron a la app que las instaló.", .fr: "Ouverture et extensions liste désormais les extensions système elles-mêmes : ce qu’elles sont, à qui elles appartiennent et lesquelles ont survécu à leur app.", .de: "Anmeldeobjekte & Erweiterungen listet jetzt die Systemerweiterungen selbst: was sie sind, zu wem sie gehören und welche ihre App überlebt haben.", .ja: "「ログイン項目と機能拡張」がシステム機能拡張そのものを一覧表示：内容、提供元、そしてインストール元アプリが消えても残っているもの。", .zh: "“登录项与扩展”现在会列出系统扩展本身：它们是什么、属于谁，以及哪些在原应用被删除后仍然留着。", .pt: "Itens de início e extensões agora lista as próprias extensões do sistema: o que são, de quem são e quais sobreviveram ao app que as instalou."])),
                ChangeItem(kind: .upd, text: L("Per-app rules read as one line each: the app, when the rule applies, and nothing else. Both Keep Awake and VPN.", [.ru: "Правила по приложениям — по одной строке: приложение, когда правило действует, и ничего лишнего. И в «Не спать», и в VPN.", .es: "Las reglas por app ocupan una línea: la app, cuándo se aplica, y nada más. En Mantener activo y en VPN.", .fr: "Les règles par app tiennent sur une ligne : l’app, quand la règle s’applique, rien d’autre. Dans Rester éveillé comme dans VPN.", .de: "App-Regeln stehen in je einer Zeile: die App, wann die Regel gilt, sonst nichts. In Wach halten wie im VPN.", .ja: "アプリ別ルールは1行に：アプリと、適用される条件だけ。「スリープ防止」と VPN の両方で。", .zh: "按应用的规则各占一行：应用、生效时机，别无其他。“保持唤醒”与 VPN 均是如此。", .pt: "As regras por app cabem em uma linha: o app, quando a regra vale, e nada mais. No Manter ativo e no VPN."])),
                ChangeItem(kind: .new, text: L("An app that keeps the Mac awake can now be narrowed to the situation you mean: only with an external display, only on power, or both.", [.ru: "Приложение, не дающее Mac спать, теперь можно ограничить условием: только при внешнем дисплее, только при питании или и то и другое.", .es: "Una app que mantiene activo el Mac ahora puede limitarse: solo con pantalla externa, solo con corriente, o ambas.", .fr: "Une app qui garde le Mac éveillé peut désormais être limitée : seulement avec un écran externe, seulement sur secteur, ou les deux.", .de: "Eine App, die den Mac wach hält, lässt sich jetzt eingrenzen: nur mit externem Bildschirm, nur am Netzstrom oder beides.", .ja: "Mac を起こし続けるアプリに条件を付けられます：外部ディスプレイ接続時のみ、電源接続時のみ、またはその両方。", .zh: "让 Mac 保持唤醒的应用现在可以限定条件：仅连接外接显示器时、仅接通电源时，或两者同时。", .pt: "Um app que mantém o Mac ativo agora pode ser limitado: só com tela externa, só na tomada, ou ambos."])),
                ChangeItem(kind: .upd, text: L("Anything that needs a system permission now says so where you turn it on — Disk, App Uninstaller, Login Items and Keep Awake all warn before they can disappoint you.", [.ru: "Всё, чему нужно разрешение системы, теперь предупреждает прямо там, где вы это включаете — «Диск», «Удаление приложений», «Объекты входа и расширения» и «Не спать».", .es: "Todo lo que necesita un permiso del sistema ahora lo indica donde se activa — Disco, Desinstalador, Ítems de inicio y Mantener activo.", .fr: "Tout ce qui exige une autorisation système le signale là où vous l’activez — Disque, Désinstallation, Ouverture et Rester éveillé.", .de: "Alles, was eine Systemberechtigung braucht, sagt das dort, wo du es einschaltest — Festplatte, Deinstallation, Anmeldeobjekte und Wach halten.", .ja: "システムの許可が必要な機能は、オンにするその場で知らせます（ディスク、アンインストーラ、ログイン項目、スリープ防止）。", .zh: "凡需要系统权限的功能，都会在你开启处提示——磁盘、卸载器、登录项与保持唤醒。", .pt: "Tudo que precisa de permissão do sistema agora avisa onde você ativa — Disco, Desinstalador, Itens de início e Manter ativo."])),
                ChangeItem(kind: .upd, text: L("Settings are ordered by how often you need them — what Helm looks like first, permissions and diagnostics last — and Keep Awake keeps all four of its automatic rules in one place.", [.ru: "Настройки выстроены по частоте: сначала то, как Helm выглядит, разрешения и диагностика — в конце; а все четыре правила автоматики «Не спать» собраны в одном разделе.", .es: "Los ajustes están ordenados por uso: primero cómo se ve Helm, permisos y diagnóstico al final; y Mantener activo reúne sus cuatro reglas automáticas en un solo lugar.", .fr: "Les réglages sont classés par fréquence d’usage : l’apparence d’abord, autorisations et diagnostic à la fin ; et Rester éveillé regroupe ses quatre règles automatiques.", .de: "Die Einstellungen sind nach Häufigkeit sortiert — Aussehen zuerst, Berechtigungen und Diagnose zuletzt — und Wach halten fasst seine vier Automatikregeln zusammen.", .ja: "設定は使用頻度順に並べ替え（見た目が先、アクセス権と診断は最後）、「スリープ防止」の4つの自動ルールは1か所にまとめました。", .zh: "设置按使用频率排列——外观在前，权限与诊断在后；“保持唤醒”的四条自动规则也归为一处。", .pt: "Os ajustes seguem a frequência de uso — aparência primeiro, permissões e diagnóstico por último — e o Manter ativo reúne suas quatro regras automáticas."])),
                ChangeItem(kind: .fix, text: L("Accessibility now appears among the permissions, and Keep Awake says so right at the pointer setting — without that grant macOS ignores the nudge and the switch did nothing.", [.ru: "«Универсальный доступ» появился среди разрешений, а «Не спать» предупреждает об этом прямо у настройки указателя: без него macOS игнорирует движение, и переключатель ничего не делал.", .es: "La Accesibilidad ahora figura entre los permisos, y Mantener activo lo advierte junto al ajuste del puntero: sin ese permiso macOS ignora el movimiento y el interruptor no hacía nada.", .fr: "L’Accessibilité figure désormais parmi les autorisations, et Rester éveillé le signale au niveau du réglage du pointeur : sans elle, macOS ignore le mouvement et l’interrupteur ne faisait rien.", .de: "Die Bedienungshilfen stehen jetzt bei den Berechtigungen, und Wach halten weist direkt an der Zeiger-Einstellung darauf hin — ohne die Freigabe ignoriert macOS die Bewegung und der Schalter blieb wirkungslos.", .ja: "アクセシビリティをアクセス権の一覧に追加し、「スリープ防止」ではポインタ設定のすぐ横に注意を表示します。許可がないと macOS は動きを無視し、スイッチは無効でした。", .zh: "无障碍已列入权限，“保持唤醒”也会在指针设置旁提示：没有该权限时 macOS 会忽略移动，开关形同虚设。", .pt: "A Acessibilidade agora aparece entre as permissões, e o Manter ativo avisa junto ao ajuste do ponteiro — sem ela o macOS ignora o movimento e o interruptor não fazia nada."])),
                ChangeItem(kind: .fix, text: L("The module order you set is now used everywhere — the panel, the sidebar in Settings, and the icon’s menu — and it no longer gets lost when a drag is abandoned.", [.ru: "Заданный вами порядок модулей теперь действует везде — в панели, в боковом меню настроек и в меню иконки — и больше не теряется, если перетаскивание прервано.", .es: "El orden de módulos que estableces ahora se usa en todas partes — el panel, la barra lateral y el menú del icono — y ya no se pierde si cancelas un arrastre.", .fr: "L’ordre des modules que vous définissez s’applique désormais partout — panneau, barre latérale et menu de l’icône — et ne se perd plus si un glissement est interrompu.", .de: "Die von dir gesetzte Modulreihenfolge gilt jetzt überall — Panel, Seitenleiste und Symbolmenü — und geht bei einem abgebrochenen Ziehen nicht mehr verloren.", .ja: "設定したモジュールの並び順が、パネル・設定のサイドバー・アイコンメニューのすべてに反映され、ドラッグを中断しても失われなくなりました。", .zh: "你设置的模块顺序现在在各处生效——面板、设置侧边栏和图标菜单——并且中断拖动也不会丢失。", .pt: "A ordem de módulos que você define agora vale em todo lugar — painel, barra lateral e menu do ícone — e não se perde se um arraste for interrompido."])),
                ChangeItem(kind: .upd, text: L("Panels and cards now look the same on every screen: one border-free container, and the figures at the top of a module line up with the settings below them.", [.ru: "Панели и карточки теперь выглядят одинаково на всех экранах: один вид блока без рамки, а цифры вверху модуля выровнены по настройкам под ними.", .es: "Paneles y tarjetas se ven igual en todas las pantallas: un solo contenedor sin borde, y las cifras de arriba se alinean con los ajustes de abajo.", .fr: "Panneaux et cartes ont le même aspect partout : un seul conteneur sans bordure, et les chiffres en haut s’alignent sur les réglages en dessous.", .de: "Panels und Karten sehen überall gleich aus: ein randloser Container, und die Kennzahlen oben fluchten mit den Einstellungen darunter.", .ja: "パネルとカードの見た目を全画面で統一：枠線のない一種類のコンテナにし、上部の数値を下の設定と揃えました。", .zh: "面板与卡片在所有页面统一：单一无边框容器，顶部数字与下方设置对齐。", .pt: "Painéis e cartões ficam iguais em todas as telas: um único contêiner sem borda, e os números do topo alinhados com os ajustes abaixo."])),
            ]),
            ChangelogEntry(version: "0.7.0", date: "2026-07-26", items: [
                ChangeItem(kind: .new, text: L("Disk Space: a ring showing what filled your disk. Click a wedge to go deeper, the middle to come back — folders carry the names Finder gives them, and anything you want gone collects in one list before it goes to the Trash.", [.ru: "«Место на диске»: кольцо показывает, чем занят диск. Клик по сегменту — вглубь, по центру — назад. Папки называются так же, как в Finder, а всё лишнее собирается в один список и разом уходит в Корзину.", .es: "Espacio en disco: un anillo que muestra qué llenó el disco. Clic en un sector para entrar, en el centro para volver; las carpetas usan los nombres del Finder y lo que sobra se reúne en una lista antes de ir a la Papelera.", .fr: "Espace disque : un anneau montre ce qui remplit le disque. Cliquez un secteur pour entrer, le centre pour revenir ; les dossiers portent leur nom du Finder, et ce qui doit partir se rassemble dans une liste avant la corbeille.", .de: "Speicherplatz: Ein Ring zeigt, was die Platte füllt. Segment anklicken für tiefer, Mitte für zurück; Ordner tragen ihre Finder-Namen, und alles Überflüssige sammelt sich in einer Liste und wandert gemeinsam in den Papierkorb.", .ja: "ディスク容量：何が容量を使っているかをリングで表示。セグメントをクリックで深く、中心で戻る。フォルダ名は Finder と同じで、不要なものは一覧にまとめてからゴミ箱へ。", .zh: "磁盘空间：用环形图显示磁盘被什么占用。点击扇区深入，点击中心返回；文件夹使用访达中的名称，要删的先收进一处再一起移到废纸篓。", .pt: "Espaço em disco: um anel mostra o que encheu o disco. Clique num setor para entrar, no centro para voltar; as pastas usam os nomes do Finder e o que deve sair se junta numa lista antes de ir para o Lixo."])),
                ChangeItem(kind: .new, text: L("Disk Space suggests what to free: bloated caches, old downloads and big files untouched for months — one tap adds them to the basket. The scan result now survives switching modules and is kept for a day.", [.ru: "«Место на диске» подсказывает, что освободить: разросшиеся кеши, старые загрузки и большие файлы, к которым давно не прикасались — одно нажатие кладёт их в корзину. Результат скана больше не пропадает при переходе между модулями и хранится сутки.", .es: "Espacio en disco sugiere qué liberar: cachés crecidas, descargas antiguas y archivos grandes sin tocar durante meses — un clic los añade a la cesta. El resultado del escaneo sobrevive al cambio de módulo y se conserva un día.", .fr: "Espace disque suggère quoi libérer : caches enflés, anciens téléchargements et gros fichiers intouchés depuis des mois — un clic les ajoute au panier. Le résultat de l’analyse survit au changement de module et reste valable un jour.", .de: "Speicherplatz schlägt vor, was Platz freigibt: gewachsene Caches, alte Downloads und große, monatelang unberührte Dateien — ein Klick legt sie in den Korb. Das Scan-Ergebnis übersteht jetzt den Modulwechsel und bleibt einen Tag erhalten.", .ja: "ディスク容量が空けられるものを提案：肥大化したキャッシュ、古いダウンロード、数か月未使用の大きなファイル。ワンクリックでバスケットへ。スキャン結果はモジュールを切り替えても消えず、1日保持されます。", .zh: "磁盘空间会建议可释放的内容：膨胀的缓存、旧下载和数月未动的大文件——点一下即可加入收集篮。扫描结果在切换模块后保留，有效期一天。", .pt: "Espaço em disco sugere o que liberar: caches inchados, downloads antigos e arquivos grandes sem uso há meses — um clique os põe na cesta. O resultado do escaneamento sobrevive à troca de módulo e fica guardado por um dia."])),
                ChangeItem(kind: .new, text: L("Disk Space remembers its last scan: reopen Helm and the ring is already there, labelled with when it was measured. Deleting no longer triggers a full rescan — the ring updates in place.", [.ru: "«Место на диске» помнит последний скан: откройте Helm — кольцо уже на месте, с подписью, когда оно измерено. Удаление больше не запускает полное пересканирование — кольцо обновляется на месте.", .es: "Espacio en disco recuerda su último escaneo: al reabrir Helm el anillo ya está, con la hora en que se midió. Eliminar ya no fuerza un reescaneo completo: el anillo se actualiza en el acto.", .fr: "Espace disque se souvient de sa dernière analyse : rouvrez Helm et l’anneau est déjà là, daté. Supprimer ne relance plus une analyse complète — l’anneau se met à jour sur place.", .de: "Speicherplatz merkt sich den letzten Scan: Helm öffnen und der Ring ist schon da, mit dem Zeitpunkt der Messung. Löschen startet keinen kompletten Neuscan mehr — der Ring aktualisiert sich direkt.", .ja: "ディスク容量は前回のスキャンを記憶します。Helm を開けばリングはすでに表示され、計測時刻も表示。削除しても全体の再スキャンは走らず、その場で更新されます。", .zh: "磁盘空间会记住上次扫描：重新打开 Helm，环形图已在，并标注测量时间。删除不再触发整盘重扫，环形图就地更新。", .pt: "Espaço em disco lembra o último escaneamento: reabra o Helm e o anel já está lá, com a hora da medição. Excluir não dispara mais um reescaneamento completo — o anel se atualiza no lugar."])),
                ChangeItem(kind: .new, text: L("Login Items & Extensions: see everything that loads with your Mac, marked as in use, system, or leftover — and remove the leftovers.", [.ru: "«Объекты входа и расширения»: видно всё, что грузится вместе с Mac, с пометками «используется», «системный» и «остаток» — остатки можно удалить.", .es: "Ítems de inicio y extensiones: mira todo lo que se carga con tu Mac, marcado como en uso, del sistema o resto — y elimina los restos.", .fr: "Ouverture et extensions : voyez tout ce qui se charge avec votre Mac, marqué en cours d’utilisation, système ou résidu — et supprimez les résidus.", .de: "Anmeldeobjekte & Erweiterungen: alles sehen, was mit dem Mac lädt — als in Benutzung, System oder Rest markiert — und die Reste entfernen.", .ja: "ログイン項目と機能拡張：Mac と一緒に読み込まれるものを「使用中」「システム」「残存物」の印付きで一覧表示し、残存物を削除できます。", .zh: "登录项与扩展：查看随 Mac 一起加载的所有项目，标记为使用中、系统或残留——并删除残留项。", .pt: "Itens de início e extensões: veja tudo que carrega com o seu Mac, marcado como em uso, do sistema ou resto — e remova os restos."])),
                ChangeItem(kind: .new, text: L("App Uninstaller works in two steps: tick the apps you want gone, then review the files found for each of them before anything moves. Apps that are still running are flagged and only removed if you allow a force quit.", [.ru: "Удаление приложений — в два шага: отметьте приложения, затем разберите найденные файлы по каждой из них, прежде чем что-то удалять. Запущенные приложения помечаются и удаляются только с вашего разрешения на принудительное завершение.", .es: "El Desinstalador funciona en dos pasos: marca las apps y revisa los archivos de cada una antes de eliminar nada. Las apps en ejecución se señalan y solo se eliminan si permites forzar la salida.", .fr: "La désinstallation se fait en deux étapes : cochez les apps, puis vérifiez les fichiers trouvés pour chacune avant toute suppression. Les apps en cours sont signalées et supprimées seulement si vous autorisez la fermeture forcée.", .de: "Die Deinstallation läuft in zwei Schritten: Apps ankreuzen, dann die gefundenen Dateien prüfen, bevor etwas entfernt wird. Laufende Apps werden markiert und nur nach erlaubtem Sofort-Beenden entfernt.", .ja: "アンインストールは2ステップ：アプリを選び、各アプリの検出ファイルを確認してから削除します。実行中のアプリは印が付き、強制終了を許可した場合のみ削除されます。", .zh: "卸载器分两步：先勾选应用，再逐个查看找到的文件，然后再删除。运行中的应用会被标记，仅在你允许强制退出后才会删除。", .pt: "A desinstalação tem dois passos: marque os apps e revise os arquivos de cada um antes de remover. Apps em execução são sinalizados e só removidos se você permitir o encerramento forçado."])),
                ChangeItem(kind: .new, text: L("Permissions at a glance: Settings shows whether Helm has Full Disk Access and lists installed system extensions. When a file can’t be removed, Helm names the reason and links to the right setting.", [.ru: "Разрешения на виду: в настройках видно, есть ли у Helm доступ к диску, и перечислены системные расширения. Если файл удалить не удалось, Helm называет причину и ведёт в нужную настройку.", .es: "Permisos a la vista: Ajustes muestra si Helm tiene Acceso total al disco y lista las extensiones del sistema. Si un archivo no se puede eliminar, Helm indica el motivo y enlaza al ajuste correcto.", .fr: "Autorisations en un coup d’œil : les Réglages indiquent si Helm a l’accès complet au disque et listent les extensions système. Si un fichier ne peut être supprimé, Helm en donne la raison et ouvre le bon réglage.", .de: "Berechtigungen im Blick: Die Einstellungen zeigen, ob Helm Festplattenvollzugriff hat, und listen Systemerweiterungen. Lässt sich eine Datei nicht entfernen, nennt Helm den Grund und verlinkt die passende Einstellung.", .ja: "アクセス権を一目で：設定でフルディスクアクセスの有無とシステム機能拡張の一覧を確認できます。削除できない場合は理由を示し、該当の設定へ案内します。", .zh: "权限一目了然：设置中显示 Helm 是否拥有完全磁盘访问权限，并列出系统扩展。文件无法删除时，Helm 会说明原因并跳转到相应设置。", .pt: "Permissões à vista: Ajustes mostra se o Helm tem Acesso Total ao Disco e lista as extensões do sistema. Quando um arquivo não pode ser removido, o Helm diz o motivo e leva ao ajuste certo."])),
                ChangeItem(kind: .new, text: L("Update channels: stay on finished releases, or switch to Dev in About to get early builds first.", [.ru: "Каналы обновлений: оставайтесь на законченных релизах или переключитесь на Dev в «О Helm», чтобы первыми получать ранние сборки.", .es: "Canales de actualización: quédate en versiones finales o cambia a Dev en Acerca de para recibir antes las compilaciones tempranas.", .fr: "Canaux de mise à jour : restez sur les versions finalisées ou passez au canal Dev dans À propos pour recevoir les versions précoces.", .de: "Update-Kanäle: bei fertigen Releases bleiben oder in Über auf Dev wechseln, um frühe Builds zuerst zu bekommen.", .ja: "アップデートチャンネル：完成版のままにするか、「Helm について」で Dev に切り替えて早期ビルドを受け取れます。", .zh: "更新通道：停留在正式版本，或在“关于”切换到 Dev 优先获取早期构建。", .pt: "Canais de atualização: fique nas versões finalizadas ou mude para Dev em Sobre para receber builds iniciais primeiro."])),
                ChangeItem(kind: .new, text: L("Drag modules into the order you want them in the menu-bar panel.", [.ru: "Перетаскивайте модули, чтобы задать их порядок в панели строки меню.", .es: "Arrastra los módulos para ordenarlos en el panel de la barra de menús.", .fr: "Faites glisser les modules pour les ordonner dans le panneau.", .de: "Module per Drag & Drop in die gewünschte Reihenfolge bringen.", .ja: "モジュールをドラッグしてメニューバーパネルでの順序を変更できます。", .zh: "拖动模块即可调整其在菜单栏面板中的顺序。", .pt: "Arraste os módulos para a ordem que quiser no painel."])),
                ChangeItem(kind: .new, text: L("Diagnostics: Helm can keep a log of what it does, ready to share when something goes wrong. Always on in Dev builds.", [.ru: "Диагностика: Helm может вести журнал своих действий, чтобы было что прислать, если что-то пошло не так. В Dev-сборках включён всегда.", .es: "Diagnóstico: Helm puede registrar lo que hace, listo para compartir si algo falla. Siempre activo en compilaciones Dev.", .fr: "Diagnostic : Helm peut tenir un journal de ses actions, prêt à partager en cas de problème. Toujours actif dans les versions Dev.", .de: "Diagnose: Helm kann protokollieren, was es tut — bereit zum Teilen, wenn etwas schiefgeht. In Dev-Builds immer an.", .ja: "診断：Helm は動作のログを記録でき、問題時にすぐ共有できます。Dev ビルドでは常時オン。", .zh: "诊断：Helm 可记录自身操作日志，出问题时随时分享。开发版始终开启。", .pt: "Diagnóstico: o Helm pode manter um registro do que faz, pronto para compartilhar se algo der errado. Sempre ativo em builds Dev."])),
                ChangeItem(kind: .upd, text: L("A new look across the app: every screen leads with its icon and the numbers that matter there, on one consistent layout.", [.ru: "Новый вид всего приложения: каждый экран начинается с иконки и своих ключевых чисел, всё — по единой сетке.", .es: "Nuevo aspecto en toda la app: cada pantalla abre con su icono y sus cifras clave, con una maquetación uniforme.", .fr: "Nouvelle allure dans toute l’app : chaque écran s’ouvre sur son icône et ses chiffres clés, sur une mise en page unifiée.", .de: "Neuer Look in der ganzen App: Jeder Bildschirm beginnt mit seinem Symbol und den wichtigen Zahlen, in einheitlichem Layout.", .ja: "アプリ全体の新しい外観：各画面はアイコンと主要な数値から始まり、レイアウトは統一されています。", .zh: "全新界面：每个页面以图标和关键数字开场，版式统一。", .pt: "Novo visual em todo o app: cada tela começa com seu ícone e os números que importam, em um layout consistente."])),
                ChangeItem(kind: .upd, text: L("Wording and sizes reviewed across the app: shorter labels, one name per thing, and sizes in your language — “432,95 ГБ”, not “432,95 GB”.", [.ru: "Пересмотрены надписи и размеры по всему приложению: короче формулировки, одно название на одну вещь, размеры на вашем языке — «432,95 ГБ», а не «432,95 GB».", .es: "Textos y tamaños revisados en toda la app: etiquetas más cortas, un nombre por cosa y tamaños en tu idioma.", .fr: "Textes et tailles revus dans toute l’app : libellés plus courts, un nom par chose, et des tailles dans votre langue.", .de: "Texte und Größen app-weit überarbeitet: kürzere Beschriftungen, ein Name pro Sache, Größen in deiner Sprache.", .ja: "アプリ全体の文言とサイズ表記を見直し：ラベルを簡潔に、名称を統一し、サイズを各言語の単位で表示。", .zh: "全应用文案与大小显示梳理：标签更简短、同一事物统一称呼、大小按你的语言显示。", .pt: "Textos e tamanhos revisados em todo o app: rótulos mais curtos, um nome por coisa e tamanhos no seu idioma."])),
            ]),
            ChangelogEntry(version: "0.6.3", date: "2026-07-25", items: [
                ChangeItem(kind: .upd, text: L("Redesigned About: the icon sits in a bezel that turns while updates are checked, version and build read as instrument dials, and update controls live in one card.", [.ru: "Новое окно «О Helm»: иконка в безеле, который вращается во время проверки обновлений, версия и сборка — как показания приборов, управление обновлениями собрано в одну карточку.", .es: "Ventana Acerca de renovada: el icono en un bisel que gira mientras se buscan actualizaciones, versión y compilación como diales, y los controles de actualización en una sola tarjeta.", .fr: "Fenêtre À propos repensée : l’icône dans un cerclage qui tourne pendant la recherche de mises à jour, version et build en cadrans, et les commandes de mise à jour réunies dans une carte.", .de: "Neu gestaltetes Über-Fenster: das Symbol in einer Lünette, die sich während der Update-Prüfung dreht, Version und Build als Instrumentenanzeige, Update-Steuerung in einer Karte.", .ja: "「Helm について」を刷新：アップデート確認中に回転するベゼル内のアイコン、計器のようなバージョンとビルド表示、更新操作を1枚のカードに集約。", .zh: "重新设计“关于”：图标置于检查更新时旋转的表圈中，版本与构建如仪表读数，更新控件集中在一张卡片。", .pt: "Janela Sobre redesenhada: o ícone num aro que gira durante a verificação de atualizações, versão e build como mostradores, e os controles de atualização em um único cartão."])),
                ChangeItem(kind: .fix, text: L("The update status no longer claims you are current when no check has run — it shows when the last check happened.", [.ru: "Статус обновлений больше не утверждает, что версия последняя, если проверки не было — показывает, когда проверяли в последний раз.", .es: "El estado de actualización ya no afirma que estás al día sin haber comprobado: muestra cuándo fue la última comprobación.", .fr: "L’état des mises à jour n’affirme plus que vous êtes à jour sans vérification : il indique la dernière vérification.", .de: "Der Update-Status behauptet nicht mehr, aktuell zu sein, ohne geprüft zu haben — er zeigt die letzte Prüfung.", .ja: "未確認のまま「最新です」と表示せず、最後に確認した時刻を表示します。", .zh: "未执行检查时不再声称已是最新，而是显示上次检查时间。", .pt: "O status de atualização não afirma mais que você está atualizado sem ter verificado — mostra a última verificação."])),
            ]),
            ChangelogEntry(version: "0.6.2", date: "2026-07-25", items: [
                ChangeItem(kind: .new, text: L("Update channels: stay on finished releases, or switch to Dev in About to get early builds.", [.ru: "Каналы обновлений: оставайтесь на законченных релизах или переключитесь на Dev в «О Helm», чтобы получать ранние сборки.", .es: "Canales de actualización: quédate en versiones finales o cambia a Dev en Acerca de para recibir compilaciones tempranas.", .fr: "Canaux de mise à jour : restez sur les versions finalisées ou passez au canal Dev dans À propos pour les versions précoces.", .de: "Update-Kanäle: bei fertigen Releases bleiben oder in Über auf Dev wechseln, um frühe Builds zu erhalten.", .ja: "アップデートチャンネル：完成版のままにするか、「Helm について」で Dev に切り替えて早期ビルドを受け取れます。", .zh: "更新通道：可停留在正式版本，或在“关于”中切换到 Dev 获取早期构建。", .pt: "Canais de atualização: fique nas versões finalizadas ou mude para Dev em Sobre para receber builds iniciais."])),
            ]),
            ChangelogEntry(version: "0.6.1", date: "2026-07-25", items: [
                ChangeItem(kind: .fix, text: L("VPN rows no longer show an endless spinner: the status is re-checked until the connection settles.", [.ru: "Строки VPN больше не показывают вечный спиннер: статус перепроверяется, пока подключение не устаканится.", .es: "Las filas de VPN ya no muestran un indicador infinito: el estado se vuelve a comprobar hasta que la conexión se estabiliza.", .fr: "Les lignes VPN n’affichent plus d’indicateur sans fin : l’état est revérifié jusqu’à stabilisation de la connexion.", .de: "VPN-Zeilen zeigen keinen endlosen Spinner mehr: der Status wird neu geprüft, bis die Verbindung steht.", .ja: "VPN の行でスピナーが回り続けなくなりました。接続が安定するまで状態を再確認します。", .zh: "VPN 行不再无限转圈：状态会持续复查直到连接稳定。", .pt: "As linhas de VPN não mostram mais um indicador infinito: o estado é verificado novamente até a conexão estabilizar."])),
            ]),
            ChangelogEntry(version: "0.6.0", date: "2026-07-25", items: [
                ChangeItem(kind: .new, text: L("App Uninstaller module: remove apps together with their caches, settings and other leftovers; find leftovers of apps that are already gone.", [.ru: "Модуль «Удаление приложений»: удаление вместе с кешами, настройками и другими хвостами; поиск остатков уже удалённых приложений.", .es: "Módulo Desinstalador: elimina apps junto con sus cachés, ajustes y otros restos; encuentra restos de apps ya eliminadas.", .fr: "Module Désinstallation : supprime les apps avec leurs caches, réglages et autres restes ; retrouve les restes d’apps déjà supprimées.", .de: "Deinstallations-Modul: entfernt Apps samt Caches, Einstellungen und anderen Resten; findet Reste bereits gelöschter Apps.", .ja: "アンインストールモジュール：キャッシュや設定などの残存ファイルごとアプリを削除。削除済みアプリの残存ファイルも検索。", .zh: "卸载器模块：连同缓存、设置等残留一并删除；还可查找已删除应用的残留。", .pt: "Módulo Desinstalador: remove apps junto com caches, ajustes e outros restos; encontra restos de apps já removidos."])),
                ChangeItem(kind: .new, text: L("Homebrew module: installed packages, updates, search and install, with a live console and package descriptions.", [.ru: "Модуль Homebrew: установленные пакеты, обновления, поиск и установка, живая консоль и описания пакетов.", .es: "Módulo Homebrew: paquetes instalados, actualizaciones, búsqueda e instalación, con consola en vivo y descripciones.", .fr: "Module Homebrew : paquets installés, mises à jour, recherche et installation, avec console en direct et descriptions.", .de: "Homebrew-Modul: installierte Pakete, Updates, Suche und Installation, mit Live-Konsole und Paketbeschreibungen.", .ja: "Homebrew モジュール：インストール済みパッケージ、アップデート、検索とインストール。ライブコンソールと説明付き。", .zh: "Homebrew 模块：已安装包、更新、搜索与安装，带实时控制台和包描述。", .pt: "Módulo Homebrew: pacotes instalados, atualizações, busca e instalação, com console ao vivo e descrições."])),
                ChangeItem(kind: .new, text: L("Menu-bar timer: the ring empties clockwise while a timer runs, with optional remaining time and its own colour.", [.ru: "Таймер в строке меню: кольцо убывает по часовой, опционально время и свой цвет.", .es: "Timer en la barra: el anillo se vacía en sentido horario, con tiempo restante y color propio opcionales.", .fr: "Minuteur dans la barre : l’anneau se vide dans le sens horaire, temps restant et couleur dédiée en option.", .de: "Menüleisten-Timer: der Ring leert sich im Uhrzeigersinn, optional mit Restzeit und eigener Farbe.", .ja: "メニューバーのタイマー：リングが時計回りに減少。残り時間表示と専用カラーも選択可。", .zh: "菜单栏计时：圆环顺时针递减，可选剩余时间与专属颜色。", .pt: "Timer na barra: o anel se esvazia no sentido horário, com tempo restante e cor própria opcionais."])),
                ChangeItem(kind: .new, text: L("Utilities live in a collapsible panel section; optional Settings and Quit buttons; the right-click menu jumps straight to any module.", [.ru: "Утилиты — в раскрывающейся секции панели; опциональные кнопки «Настройки» и «Выйти»; меню правого клика ведёт сразу в модуль.", .es: "Las utilidades viven en una sección plegable del panel; botones opcionales de Ajustes y Salir; el menú contextual salta directo a un módulo.", .fr: "Les utilitaires vivent dans une section repliable ; boutons Réglages et Quitter en option ; le menu contextuel ouvre directement un module.", .de: "Dienstprogramme in einer aufklappbaren Panel-Sektion; optionale Einstellungen/Beenden-Tasten; das Rechtsklickmenü springt direkt zum Modul.", .ja: "ユーティリティはパネルの折りたたみセクションに。設定/終了ボタンを追加可能。右クリックメニューから各モジュールへ直行。", .zh: "实用工具收纳于面板可折叠区；可选“设置/退出”按钮；右键菜单直达任意模块。", .pt: "Utilitários em seção recolhível do painel; botões opcionais Ajustes e Sair; o menu de contexto abre direto um módulo."])),
                ChangeItem(kind: .upd, text: L("Keep Awake’s ⋯ controls open inline with animation: custom timer with a durations menu, automation toggles, Stop button in the countdown.", [.ru: "Блок «⋯» открывается прямо в карточке с анимацией: свой таймер с меню длительностей, тумблеры автоматизации, «Стоп» в отсчёте.", .es: "Los controles ⋯ se abren en línea con animación: temporizador propio con menú de duraciones, automatización y botón Detener.", .fr: "Les contrôles ⋯ s’ouvrent en ligne avec animation : minuteur personnalisé avec menu de durées, automatisations, bouton Arrêter.", .de: "Die ⋯-Steuerung öffnet inline mit Animation: eigener Timer mit Dauer-Menü, Automatik-Schalter, Stopp-Taste im Countdown.", .ja: "⋯ の操作はカード内でアニメーション表示：時間メニュー付きカスタムタイマー、自動化スイッチ、停止ボタン。", .zh: "⋯ 控件在卡片内动画展开：自定义计时（时长菜单）、自动化开关、倒计时中的停止按钮。", .pt: "Os controles ⋯ abrem na própria carta com animação: timer com menu de durações, automações e botão Parar."])),
                ChangeItem(kind: .upd, text: L("Settings window polish: larger window for utility pages, macOS 26-style lists, clearer wording throughout.", [.ru: "Полировка окна настроек: увеличенное окно для утилит, списки в стиле macOS 26, выверенные тексты.", .es: "Pulido de Ajustes: ventana mayor para utilidades, listas al estilo macOS 26, textos más claros.", .fr: "Réglages peaufinés : fenêtre agrandie pour les utilitaires, listes façon macOS 26, textes clarifiés.", .de: "Einstellungen poliert: größeres Fenster für Dienstprogramme, Listen im macOS-26-Stil, klarere Texte.", .ja: "設定ウインドウを改良：ユーティリティは大きめのウインドウ、macOS 26 スタイルのリスト、文言を整理。", .zh: "设置窗口打磨：实用工具使用更大窗口、macOS 26 风格列表、更清晰的文案。", .pt: "Ajustes refinados: janela maior para utilitários, listas no estilo macOS 26, textos mais claros."])),
                ChangeItem(kind: .fix, text: L("The panel no longer jumps or slides when sections expand; settings stay in sync between the panel and the Settings window.", [.ru: "Панель больше не прыгает при раскрытии секций; настройки синхронизированы между панелью и окном настроек.", .es: "El panel ya no salta al expandir secciones; los ajustes se sincronizan entre panel y ventana.", .fr: "Le panneau ne saute plus à l’ouverture des sections ; les réglages restent synchronisés entre panneau et fenêtre.", .de: "Das Panel springt beim Aufklappen nicht mehr; Einstellungen bleiben zwischen Panel und Fenster synchron.", .ja: "セクション展開時にパネルが跳ねなくなり、パネルと設定ウインドウの設定が同期されます。", .zh: "展开区块时面板不再跳动；面板与设置窗口的设置保持同步。", .pt: "O painel não pula mais ao expandir seções; os ajustes ficam sincronizados entre painel e janela."])),
                ChangeItem(kind: .fix, text: L("The menu-bar countdown ticks reliably; heavy work no longer stalls the app’s async machinery.", [.ru: "Отсчёт в строке меню тикает стабильно; тяжёлые операции больше не тормозят асинхронику приложения.", .es: "La cuenta atrás avanza de forma fiable; el trabajo pesado ya no atasca la maquinaria asíncrona.", .fr: "Le compte à rebours avance de façon fiable ; les tâches lourdes ne bloquent plus l’asynchrone.", .de: "Der Countdown tickt zuverlässig; schwere Arbeit bremst die Async-Maschinerie nicht mehr.", .ja: "メニューバーのカウントダウンが確実に進み、重い処理が非同期機構を塞がなくなりました。", .zh: "菜单栏倒计时稳定走动；繁重任务不再阻塞异步机制。", .pt: "A contagem na barra avança de forma confiável; trabalho pesado não trava mais a máquina assíncrona."])),
            ]),
            ChangelogEntry(version: "0.5.1", date: "2026-07-24", items: [
                ChangeItem(kind: .fix, text: L("Silent update cleans up its temporary files after installing.", [.ru: "Тихое обновление подчищает временные файлы после установки.", .es: "La actualización silenciosa limpia sus archivos temporales tras instalar.", .fr: "La mise à jour silencieuse nettoie ses fichiers temporaires après installation.", .de: "Das stille Update räumt seine temporären Dateien nach der Installation auf.", .ja: "サイレントアップデートがインストール後に一時ファイルを削除します。", .zh: "静默更新安装后清理临时文件。", .pt: "A atualização silenciosa limpa os arquivos temporários após instalar."])),
            ]),
            ChangelogEntry(version: "0.5.0", date: "2026-07-24", items: [
                ChangeItem(kind: .new, text: L("Silent in-app updates: Update & Relaunch downloads, installs and restarts with no Gatekeeper prompt.", [.ru: "Тихие обновления: «Обновить и перезапустить» скачивает, ставит и перезапускает без запросов Gatekeeper.", .es: "Actualizaciones silenciosas: Actualizar y reiniciar descarga, instala y reinicia sin avisos de Gatekeeper.", .fr: "Mises à jour silencieuses : Mettre à jour et relancer télécharge, installe et redémarre sans invite Gatekeeper.", .de: "Stille Updates: Aktualisieren & neu starten lädt, installiert und startet neu ohne Gatekeeper-Abfrage.", .ja: "サイレント更新：「更新して再起動」がダウンロード・インストール・再起動まで自動で行います。", .zh: "静默更新：“更新并重启”自动下载、安装并重启，无 Gatekeeper 提示。", .pt: "Atualizações silenciosas: Atualizar e reiniciar baixa, instala e reinicia sem avisos do Gatekeeper."])),
            ]),
            ChangelogEntry(version: "0.4.0", date: "2026-07-24", items: [
                ChangeItem(kind: .new, text: L("Custom active-state icon for Keep Awake.", [.ru: "Своя иконка активного состояния для «Не спать».", .es: "Icono activo personalizado para Mantener activo.", .fr: "Icône active personnalisée pour Rester éveillé.", .de: "Eigenes Aktiv-Symbol für Wach halten.", .ja: "スリープ防止のカスタムアクティブアイコン。", .zh: "保持唤醒的自定义激活图标。", .pt: "Ícone ativo personalizado para Manter ativo."])),
                ChangeItem(kind: .upd, text: L("Reworked icon pickers with real-size previews; smaller icon sizes.", [.ru: "Переработанные пикеры иконки с превью в реальном размере; меньшие размеры.", .es: "Selectores de icono renovados con vistas a tamaño real; tamaños más pequeños.", .fr: "Sélecteurs d’icône repensés avec aperçus à taille réelle ; tailles plus petites.", .de: "Überarbeitete Symbol-Auswahl mit Vorschau in Originalgröße; kleinere Größen.", .ja: "実寸プレビュー付きの新しいアイコンピッカー。より小さいサイズも追加。", .zh: "重做的图标选择器（实际尺寸预览）；新增更小尺寸。", .pt: "Seletores de ícone renovados com prévia em tamanho real; tamanhos menores."])),
            ]),
            ChangelogEntry(version: "0.3.0", date: "2026-07-24", items: [
                ChangeItem(kind: .upd, text: L("Update check moved into About.", [.ru: "Проверка обновлений переехала в «О Helm».", .es: "La comprobación de actualizaciones se movió a Acerca de.", .fr: "La vérification des mises à jour a déménagé dans À propos.", .de: "Die Update-Prüfung ist nach Über umgezogen.", .ja: "アップデート確認を「Helm について」に移動。", .zh: "更新检查移至“关于”。", .pt: "A verificação de atualizações foi para Sobre."])),
                ChangeItem(kind: .fix, text: L("Panel toggles show the real state right after launch.", [.ru: "Тумблеры панели показывают реальное состояние сразу после запуска.", .es: "Los interruptores del panel muestran el estado real justo tras el arranque.", .fr: "Les interrupteurs du panneau montrent l’état réel dès le lancement.", .de: "Panel-Schalter zeigen direkt nach dem Start den echten Zustand.", .ja: "起動直後からパネルのスイッチが実際の状態を表示。", .zh: "启动后面板开关即显示真实状态。", .pt: "Os interruptores do painel mostram o estado real logo após o início."])),
            ]),
            ChangelogEntry(version: "0.2.0", date: "2026-07-24", items: [
                ChangeItem(kind: .new, text: L("GitHub update check and the What’s New window.", [.ru: "Проверка обновлений через GitHub и окно «Что нового».", .es: "Comprobación de actualizaciones por GitHub y ventana Novedades.", .fr: "Vérification des mises à jour via GitHub et fenêtre Nouveautés.", .de: "GitHub-Update-Prüfung und das Neuigkeiten-Fenster.", .ja: "GitHub 経由のアップデート確認と「新機能」ウインドウ。", .zh: "GitHub 更新检查与“新增内容”窗口。", .pt: "Verificação de atualizações via GitHub e a janela Novidades."])),
            ]),
            ChangelogEntry(version: "0.1.0", date: "2026-07-23", items: [
                ChangeItem(kind: .new, text: L("Keep Awake module: manual, timed or automatic (external display, power, chosen apps), closed-lid mode, battery guard, global hotkey.", [.ru: "Модуль «Не спать»: вручную, по таймеру или автоматически (внешний дисплей, питание, выбранные приложения), режим с закрытой крышкой, защита батареи, глобальный хоткей.", .es: "Módulo Mantener activo: manual, con temporizador o automático (pantalla externa, corriente, apps elegidas), tapa cerrada, protección de batería, atajo global.", .fr: "Module Rester éveillé : manuel, minuté ou automatique (écran externe, secteur, apps choisies), capot fermé, protection batterie, raccourci global.", .de: "Wach-halten-Modul: manuell, per Timer oder automatisch (externer Bildschirm, Netzstrom, gewählte Apps), geschlossener Deckel, Batterieschutz, globaler Kurzbefehl.", .ja: "スリープ防止モジュール：手動・タイマー・自動（外部ディスプレイ、電源、選択アプリ）、クラムシェル、バッテリー保護、グローバルショートカット。", .zh: "保持唤醒模块：手动、定时或自动（外接显示器、电源、指定应用）、合盖模式、电池保护、全局快捷键。", .pt: "Módulo Manter ativo: manual, por timer ou automático (tela externa, energia, apps escolhidos), tampa fechada, proteção de bateria, atalho global."])),
                ChangeItem(kind: .new, text: L("VPN module: connect and disconnect system VPNs with per-app auto-connect rules.", [.ru: "Модуль VPN: подключение и отключение системных VPN с авто-подключением по приложениям.", .es: "Módulo VPN: conecta y desconecta VPN del sistema con reglas por app.", .fr: "Module VPN : connexion/déconnexion des VPN système avec règles par app.", .de: "VPN-Modul: System-VPNs verbinden/trennen mit App-Regeln.", .ja: "VPN モジュール：システム VPN の接続/切断とアプリ別自動接続。", .zh: "VPN 模块：连接/断开系统 VPN，支持按应用自动连接。", .pt: "Módulo VPN: conecta e desconecta VPNs do sistema com regras por app."])),
                ChangeItem(kind: .new, text: L("Menu-bar panel and a System Settings-style window, the Liquid Glass icon, eight languages.", [.ru: "Панель в строке меню и окно в стиле Системных настроек, иконка Liquid Glass, восемь языков.", .es: "Panel en la barra y ventana al estilo Ajustes del Sistema, icono Liquid Glass, ocho idiomas.", .fr: "Panneau de barre des menus et fenêtre façon Réglages Système, icône Liquid Glass, huit langues.", .de: "Menüleisten-Panel und Fenster im Systemeinstellungen-Stil, Liquid-Glass-Symbol, acht Sprachen.", .ja: "メニューバーパネルとシステム設定風ウインドウ、Liquid Glass アイコン、8 言語対応。", .zh: "菜单栏面板与系统设置风格窗口、Liquid Glass 图标、八种语言。", .pt: "Painel na barra e janela no estilo Ajustes do Sistema, ícone Liquid Glass, oito idiomas."])),
            ]),
        ]
    }
